declare
  m public.dispo_ankunft_melden%rowtype;
  j record;
  live public.driver_live_locations%rowtype;
  hat_live boolean;
  heute date := (now() at time zone 'Europe/Berlin')::date;
  jetzt timestamptz := now();
  v_fahrt constant text[] := array['in_progress', 'unterwegs', 'started', 'on_trip', 'ongoing', 'active'];
  v_beim_gast constant text[] := array['at_pickup', 'pickup', 'beim_pickup', 'beim pickup'];
  v_fertig constant text[] := array['done', 'completed', 'arrived', 'beendet'];
  v_weg constant text[] := array['cancelled', 'canceled', 'refused', 'storniert', 'stoniert'];
  st text;
  t_lat double precision;
  t_lng double precision;
  sync_at timestamptz;
  sync_min numeric;
  luft integer;
  tempo numeric;
  dauer numeric;
begin
  select * into m from public.dispo_ankunft_melden d
  where d.user_id = p_user and d.an and d.lat is not null and d.lng is not null;
  if not found then return; end if;

  for j in
    select x.*,
      coalesce(po.lat, (x.ext_route_payload->'von'->>'lat')::float8,
               (x.ext_driver_to_pickup_payload->'nach'->>'lat')::float8) as p_lat,
      coalesce(po.lng, (x.ext_route_payload->'von'->>'lon')::float8, (x.ext_route_payload->'von'->>'lng')::float8,
               (x.ext_driver_to_pickup_payload->'nach'->>'lon')::float8) as p_lng,
      coalesce(zo.lat, (x.ext_route_payload->'nach'->>'lat')::float8,
               (x.ext_driver_to_dropoff_payload->'nach'->>'lat')::float8) as z_lat,
      coalesce(zo.lng, (x.ext_route_payload->'nach'->>'lon')::float8, (x.ext_route_payload->'nach'->>'lng')::float8,
               (x.ext_driver_to_dropoff_payload->'nach'->>'lon')::float8) as z_lng
    from public.jobs x
    left join public.orte po on po.id = x.pickup_ort_id
    left join public.orte zo on zo.id = x.dropoff_ort_id
    where x.ride_date between heute - 1 and heute + 1
      and public.trisar_norm_status(x.status) <> all (v_weg)
      and not exists (select 1 from public.jobs_archive a where a.job_id = x.id)
  loop
    st := public.trisar_norm_status(j.status);

    hat_live := false;
    if j.driver_id is not null then
      select * into live from public.driver_live_locations l
      where l.driver_id = j.driver_id
        and coalesce(l.captured_at, l.updated_at) > jetzt - interval '3 minutes'
        and l.lat is not null and l.lng is not null;
      hat_live := found;
    end if;

    -- Tempo der geplanten Route in m/min (fuer die Schaetzung aus der Luftlinie)
    dauer := coalesce(j.ext_route_duration_in_traffic_mins, j.ext_route_duration_mins);
    tempo := case when coalesce(j.ext_route_distance_m, 0) > 0 and coalesce(dauer, 0) > 0
                  then least(1500, greatest(200, j.ext_route_distance_m / dauer)) else 500 end;

    -- Fahrt endet bei mir
    if j.z_lat is not null
       and public.trisar_luftlinie_m(j.z_lat, j.z_lng, m.lat, m.lng) <= m.umkreis_m
       and (j.ride_date = heute or st = any (v_fahrt)) then
      t_lat := j.z_lat; t_lng := j.z_lng;
      job_id := j.id; art := 'ziel'; driver_id := j.driver_id;
      rest_min := null; geschaetzt := false; angekommen := false;
      if st = any (v_fertig) then
        -- beendet: nur kurz als angekommen zeigen
        if exists (select 1 from public.job_status_history h
                   where h.job_id = j.id and public.trisar_norm_status(h.to_status) = any (v_fertig)
                     and h.created_at > jetzt - interval '30 minutes') then
          angekommen := true;
          return next;
        end if;
      elsif st = any (v_fahrt) then
        luft := case when hat_live then public.trisar_luftlinie_m(live.lat, live.lng, t_lat, t_lng) end;
        sync_at := j.ext_driver_to_dropoff_last_sync_at;
        sync_min := coalesce(j.ext_driver_to_dropoff_duration_in_traffic_mins, j.ext_driver_to_dropoff_duration_mins);
        if luft is not null and luft <= 150 then
          angekommen := true; rest_min := 0;
        elsif sync_at > jetzt - interval '3 minutes' and sync_min is not null then
          rest_min := greatest(0, round(extract(epoch from sync_at + make_interval(mins => sync_min::int) - jetzt) / 60))::int;
        elsif luft is not null then
          rest_min := ceil(luft * 1.3 / tempo)::int; geschaetzt := true;
        end if;
        return next;
      else
        return next;  -- geplant, noch nicht mit Gast unterwegs
      end if;
    end if;

    -- Fahrt beginnt bei mir (Fahrer kommt zum Abholen)
    if j.p_lat is not null
       and public.trisar_luftlinie_m(j.p_lat, j.p_lng, m.lat, m.lng) <= m.umkreis_m
       and j.ride_date = heute
       and st <> all (v_fahrt) and st <> all (v_fertig) then
      t_lat := j.p_lat; t_lng := j.p_lng;
      job_id := j.id; art := 'abholung'; driver_id := j.driver_id;
      rest_min := null; geschaetzt := false; angekommen := false;
      if st = any (v_beim_gast) then
        angekommen := true; rest_min := 0;
      elsif j.driver_id is not null
            and j.etd is not null
            and (j.ride_date + j.etd) at time zone 'Europe/Berlin' between jetzt - interval '1 hour' and jetzt + interval '2 hours'
            -- Fahrer faehrt gerade keine andere Fahrt, sonst waere die Anfahrt falsch
            and not exists (select 1 from public.jobs o
                            where o.driver_id = j.driver_id and o.id <> j.id
                              and public.trisar_norm_status(o.status) = any (v_fahrt)) then
        luft := case when hat_live then public.trisar_luftlinie_m(live.lat, live.lng, t_lat, t_lng) end;
        sync_at := j.ext_driver_to_pickup_last_sync_at;
        sync_min := coalesce(j.ext_driver_to_pickup_duration_in_traffic_mins, j.ext_driver_to_pickup_duration_mins);
        if luft is not null and luft <= 150 then
          angekommen := true; rest_min := 0;
        elsif sync_at > jetzt - interval '3 minutes' and sync_min is not null then
          rest_min := greatest(0, round(extract(epoch from sync_at + make_interval(mins => sync_min::int) - jetzt) / 60))::int;
        elsif luft is not null then
          rest_min := ceil(luft * 1.3 / 500)::int; geschaetzt := true;
        end if;
      end if;
      return next;
    end if;
  end loop;
end;

declare
  d record;
  v jsonb;
  tag text;
  k uuid;
begin
  select * into d from public.driver_service_requests where id = p_id;
  if not found then
    raise exception 'Dienst nicht gefunden';
  end if;
  if d.driver_id is distinct from auth.uid() then
    raise exception 'kein Zugriff';
  end if;
  select a.vorher into v from public.dienst_aenderung a where a.dienst_id = p_id;

  if p_annehmen then
    update public.driver_service_requests set status = 'accepted' where id = p_id;
    delete from public.dienst_aenderung where dienst_id = p_id;
    return 'accepted';
  end if;

  if v is null then
    update public.driver_service_requests set status = 'refused' where id = p_id;
    return 'refused';
  end if;

  -- Aenderung abgelehnt: alter Stand gilt wieder, Dienst bleibt angenommen. Ohne die ueblichen Pushes.
  perform set_config('trisar.dienst_antwort', '1', true);
  update public.driver_service_requests
     set service_start_time = nullif(v->>'start', '')::time,
         service_end_time = nullif(v->>'ende', '')::time,
         status = 'accepted'
   where id = p_id;
  if jsonb_array_length(coalesce(v->'pausen', '[]'::jsonb)) > 0 then
    insert into public.dienst_pausen (dienst_id, pausen, aktualisiert)
    values (p_id, v->'pausen', now())
    on conflict (dienst_id) do update set pausen = excluded.pausen, aktualisiert = excluded.aktualisiert;
  else
    delete from public.dienst_pausen where dienst_id = p_id;
  end if;
  delete from public.dienst_aenderung where dienst_id = p_id;
  perform set_config('trisar.dienst_antwort', '', true);

  tag := to_char(d.service_date, 'DD.MM.') || ' ' || coalesce(nullif(v->>'start', ''), '?') || '–' || coalesce(nullif(v->>'ende', ''), '?');
  for k in select public.push_dispo_konten() loop
    perform public.push_melden(k, 'dispo', 'dispo_dienst_abgelehnt', 'Änderung abgelehnt',
      public.push_name(d.driver_id) || ' hat die Änderung am Dienst ' || to_char(d.service_date, 'DD.MM.')
        || ' abgelehnt. Es gilt wieder ' || tag || '.',
      jsonb_build_object('ziel', 'fahrer', 'user_id', d.driver_id));
  end loop;
  return 'zurueckgesetzt';
end;

declare
  z record;
  v jsonb;
  beginn timestamptz;
  ende timestamptz;
  bis timestamptz;
  p jsonb;
  p_von timestamptz;
  p_bis timestamptz;
  pause_sek double precision := 0;
begin
  select * into z from public.stundenzettel where dienst_id = p_dienst_id;
  if found and z.ende > z.beginn then
    return coalesce(z.arbeits_min, 0);
  end if;
  v := public.stunden_vorschlag_server(p_dienst_id);
  if v is null then return 0; end if;
  beginn := (v->>'beginn')::timestamptz;
  ende := (v->>'ende')::timestamptz;
  if beginn is null or beginn > now() then return 0; end if;
  bis := least(now(), coalesce(ende, now()));
  for p in select * from jsonb_array_elements(coalesce(v->'pausen', '[]'::jsonb)) loop
    p_von := (p->>'von')::timestamptz;
    p_bis := (p->>'bis')::timestamptz;
    -- Pausen unter 3 Stunden sind Arbeitszeit.
    if p_von is null or p_bis is null or p_bis - p_von < interval '3 hours' then continue; end if;
    pause_sek := pause_sek + greatest(0, extract(epoch from (least(p_bis, bis) - p_von)));
  end loop;
  return greatest(0, floor((extract(epoch from (bis - beginn)) - pause_sek) / 60))::int;
end;

begin
  if new.art not in ('bus', 'ubahn', 'tram') then
    return new;
  end if;
  if tg_op = 'UPDATE'
     and new.art is not distinct from old.art
     and new.von_lat is not distinct from old.von_lat and new.von_lng is not distinct from old.von_lng
     and new.nach_lat is not distinct from old.nach_lat and new.nach_lng is not distinct from old.nach_lng then
    return new;
  end if;
  perform public.dienstreise_linie_anstossen(array[new.id]);
  return new;
end;

begin
  update public.dienstreise_fahrer
     set status = case when p_annehmen then 'accepted' else 'refused' end, aktualisiert = now()
   where dienstreise_id = p_dienstreise and driver_id = auth.uid();
  if not found then
    raise exception 'kein Zugriff';
  end if;
  return case when p_annehmen then 'accepted' else 'refused' end;
end;

begin
  update public.dienstreise_fahrer set beendet = now(), aktualisiert = now()
   where dienstreise_id = p_dienstreise and driver_id = auth.uid() and status = 'accepted';
  if not found then
    raise exception 'kein Zugriff';
  end if;
end;

begin
  if new.driver_id is null or lower(coalesce(new.status, '')) not in ('at_pickup', 'in_progress') then
    return new;
  end if;
  if lower(coalesce(old.status, '')) in ('at_pickup', 'in_progress') then
    return new;
  end if;
  update public.dienstreise_fahrer f
     set beendet = now(), aktualisiert = now()
    from public.dienstreise r
   where f.dienstreise_id = r.id
     and f.driver_id = new.driver_id
     and lower(coalesce(f.status, '')) = 'accepted'
     and f.beendet is null
     and r.datum between (now() at time zone 'Europe/Berlin')::date - 1 and (now() at time zone 'Europe/Berlin')::date
     and now() >= coalesce(
           (select max(((coalesce(a.ab_datum, r.datum) + a.ab_zeit) at time zone 'Europe/Berlin'))
              from public.dienstreise_abschnitt a
             where a.dienstreise_id = r.id and a.ab_zeit is not null),
           ((r.datum + r.start_zeit) at time zone 'Europe/Berlin'));
  return new;
end;

begin
  if new.datum is not distinct from old.datum and new.start_zeit is not distinct from old.start_zeit
     and new.start_name is not distinct from old.start_name and new.ziel_name is not distinct from old.ziel_name
     and new.zugnummer is not distinct from old.zugnummer and new.flugnummer is not distinct from old.flugnummer then
    return new;
  end if;
  new.geaendert := now();
  update public.dienstreise_fahrer set status = 'pending', aktualisiert = now()
   where dienstreise_id = new.id and status = 'accepted';
  perform public.push_melden(f.driver_id, 'fahrer', 'dienstreise_geaendert', 'Dienstreise geändert',
    'Dienstreise ' || new.start_name || ' → ' || new.ziel_name || ' jetzt ' || to_char(new.datum, 'DD.MM.') || ' ' || to_char(new.start_zeit, 'HH24:MI') || ', bitte bestätigen.',
    jsonb_build_object('ziel', 'liste'))
  from public.dienstreise_fahrer f where f.dienstreise_id = new.id and f.status = 'pending';
  return new;
end;

declare
  v_schluessel text;
begin
  if coalesce(array_length(p_ids, 1), 0) = 0 then
    return;
  end if;
  select value #>> '{}' into v_schluessel from public.integration_settings where key = 'edge_service_role_key';
  if coalesce(v_schluessel, '') = '' then
    return;
  end if;
  perform net.http_post(
    url := 'http://kong:8000/functions/v1/dispo-admin',
    body := jsonb_build_object('aktion', 'abschnitt_linie', 'abschnitt_ids', to_jsonb(p_ids)),
    headers := jsonb_build_object('Content-Type', 'application/json',
                                  'Authorization', 'Bearer ' || v_schluessel,
                                  'apikey', v_schluessel),
    timeout_milliseconds := 60000
  );
end;

declare
  a public.dienstreise_abschnitt;
  r public.dienstreise;
  alt public.dienstreise_live;
  neu public.dienstreise_live;
  jetzt_berlin timestamp := now() at time zone 'Europe/Berlin';
  tag date;
  abgefahren boolean;
  angekommen boolean;
  spaet_ab integer;
  spaet_an integer;
  spaet integer;
  plan_ab text;
  plan_an text;
  nummer text;
  titel text;
  text_ text;
  daten jsonb;
  f uuid;
  anzahl integer := 0;
  w text;
begin
  select * into a from public.dienstreise_abschnitt where id = (p->>'abschnitt_id')::uuid;
  if not found then return 0; end if;
  select * into r from public.dienstreise where id = a.dienstreise_id;
  select * into alt from public.dienstreise_live where abschnitt_id = a.id;

  insert into public.dienstreise_live as l (abschnitt_id, dienstreise_id, abfahrt, abfahrt_plan, ankunft, ankunft_plan,
                                            gleis_ab, gleis_ab_plan, gleis_an, gleis_an_plan, stand)
  values (a.id, a.dienstreise_id, nullif(p->>'abfahrt', ''), nullif(p->>'abfahrt_plan', ''), nullif(p->>'ankunft', ''),
          nullif(p->>'ankunft_plan', ''), nullif(p->>'gleis_ab', ''), nullif(p->>'gleis_ab_plan', ''),
          nullif(p->>'gleis_an', ''), nullif(p->>'gleis_an_plan', ''), now())
  on conflict (abschnitt_id) do update set
    abfahrt = excluded.abfahrt, abfahrt_plan = excluded.abfahrt_plan, ankunft = excluded.ankunft,
    ankunft_plan = excluded.ankunft_plan, gleis_ab = excluded.gleis_ab, gleis_ab_plan = excluded.gleis_ab_plan,
    gleis_an = excluded.gleis_an, gleis_an_plan = excluded.gleis_an_plan, stand = now()
  returning * into neu;

  tag := coalesce(a.ab_datum, r.datum);
  nummer := trim(a.nummer);
  plan_ab := coalesce(neu.abfahrt_plan, to_char(a.ab_zeit, 'HH24:MI'));
  plan_an := coalesce(neu.ankunft_plan, to_char(a.an_zeit, 'HH24:MI'));
  abgefahren := jetzt_berlin >= tag + coalesce(nullif(neu.abfahrt, '')::time, a.ab_zeit);
  angekommen := a.an_zeit is not null and jetzt_berlin >= coalesce(a.an_datum, tag) + coalesce(nullif(neu.ankunft, '')::time, a.an_zeit)
                + case when coalesce(nullif(neu.ankunft, '')::time, a.an_zeit) < a.ab_zeit then interval '1 day' else interval '0' end;
  if angekommen then return 0; end if;
  daten := jsonb_build_object('dienstreise_id', r.id, 'abschnitt_id', a.id);

  -- Verspaetung: vor der Abfahrt die Abfahrt, danach die Ankunft. Frueher als Plan zaehlt als puenktlich.
  spaet_ab := greatest(coalesce(public.reise_minuten_spaet(plan_ab, neu.abfahrt), 0), 0);
  spaet_an := greatest(coalesce(public.reise_minuten_spaet(plan_an, neu.ankunft), 0), 0);
  spaet := case when abgefahren then spaet_an else greatest(spaet_ab, spaet_an) end;
  if abs(spaet - coalesce(alt.gemeldet_spaet, 0)) >= 5 then
    if spaet >= 5 then
      titel := nummer || ' +' || spaet || ' min';
    else
      titel := nummer || ' wieder pünktlich';
    end if;
    if abgefahren then
      text_ := 'Ankunft ' || coalesce(nullif(a.nach_name, ''), 'Ziel') || ' ' || coalesce(neu.ankunft, plan_an)
               || case when spaet >= 5 then ' statt ' || plan_an else '' end || '.';
    else
      text_ := 'Abfahrt ' || a.von_name || ' ' || coalesce(neu.abfahrt, plan_ab)
               || case when spaet_ab >= 5 then ' statt ' || plan_ab else '' end
               || case when neu.ankunft is not null and spaet_an >= 5 then ', Ankunft ' || neu.ankunft else '' end || '.';
    end if;
    for f in select x.driver_id from public.dienstreise_fahrer x
              where x.dienstreise_id = r.id and lower(coalesce(x.status, '')) = 'accepted' and x.beendet is null loop
      perform public.push_melden(f, 'fahrer', 'reise_verspaetung', titel, text_, daten);
      anzahl := anzahl + 1;
    end loop;
    update public.dienstreise_live set gemeldet_spaet = spaet where abschnitt_id = a.id;
  end if;

  -- Gleis bei Abfahrt (nur vor der Abfahrt): anders als im Ticket bzw. im Fahrplan, je neuem Gleis einmal.
  w := coalesce(nullif(a.gleis_ab, ''), neu.gleis_ab_plan);
  if not abgefahren and neu.gleis_ab is not null and w is not null and neu.gleis_ab <> w
     and neu.gleis_ab is distinct from alt.gemeldet_gleis_ab then
    for f in select x.driver_id from public.dienstreise_fahrer x
              where x.dienstreise_id = r.id and lower(coalesce(x.status, '')) = 'accepted' and x.beendet is null loop
      perform public.push_melden(f, 'fahrer', 'reise_gleis', nummer || ': Gleisänderung',
        'Abfahrt ' || a.von_name || ' ' || coalesce(neu.abfahrt, plan_ab) || ' jetzt Gleis ' || neu.gleis_ab
        || ' statt ' || w || '.', daten);
      anzahl := anzahl + 1;
    end loop;
    update public.dienstreise_live set gemeldet_gleis_ab = neu.gleis_ab where abschnitt_id = a.id;
  end if;

  -- Gleis bei Ankunft (bis zur Ankunft).
  w := coalesce(nullif(a.gleis_an, ''), neu.gleis_an_plan);
  if neu.gleis_an is not null and w is not null and neu.gleis_an <> w
     and neu.gleis_an is distinct from alt.gemeldet_gleis_an then
    for f in select x.driver_id from public.dienstreise_fahrer x
              where x.dienstreise_id = r.id and lower(coalesce(x.status, '')) = 'accepted' and x.beendet is null loop
      perform public.push_melden(f, 'fahrer', 'reise_gleis', nummer || ': Gleisänderung',
        'Ankunft ' || coalesce(nullif(a.nach_name, ''), 'Ziel') || ' jetzt Gleis ' || neu.gleis_an
        || ' statt ' || w || '.', daten);
      anzahl := anzahl + 1;
    end loop;
    update public.dienstreise_live set gemeldet_gleis_an = neu.gleis_an where abschnitt_id = a.id;
  end if;

  return anzahl;
end;

declare
  d record;
  beschreibung text;
  k uuid;
begin
  select * into d from public.dienstreise where id = coalesce(new.dienstreise_id, old.dienstreise_id);
  if not found then
    return coalesce(new, old);
  end if;
  beschreibung := d.start_name || ' → ' || d.ziel_name || ' ' || to_char(d.datum, 'DD.MM.') || ' ' || to_char(d.start_zeit, 'HH24:MI')
    || coalesce(' · ' || nullif(coalesce(d.zugnummer, d.flugnummer), ''), '');
  if tg_op = 'INSERT' then
    perform public.push_melden(new.driver_id, 'fahrer', 'dienstreise_neu', 'Dienstreise', 'Dienstreise ' || beschreibung || ', bitte bestätigen.', jsonb_build_object('ziel', 'liste'));
  elsif tg_op = 'DELETE' then
    perform public.push_melden(old.driver_id, 'fahrer', 'dienstreise_zurueck', 'Dienstreise zurückgezogen', 'Dienstreise ' || beschreibung || ' wurde zurückgezogen.', jsonb_build_object('ziel', 'liste'));
    return old;
  elsif new.status is distinct from old.status and new.status in ('accepted', 'refused') then
    for k in select public.push_dispo_konten() loop
      perform public.push_melden(k, 'dispo', case when new.status = 'refused' then 'dispo_dienstreise_abgelehnt' else 'dispo_dienstreise_angenommen' end,
        case when new.status = 'refused' then 'Dienstreise abgelehnt' else 'Dienstreise bestätigt' end,
        public.push_name(new.driver_id) || ' hat die Dienstreise ' || beschreibung
          || case when new.status = 'refused' then ' abgelehnt.' else ' bestätigt.' end,
        jsonb_build_object('ziel', 'fahrer', 'user_id', new.driver_id));
    end loop;
  end if;
  return new;
end;

declare
  d record;
  minuten integer;
  kosten numeric := 0;
  stunden numeric := 0;
  ohne_lohn integer := 0;
begin
  if not public.ist_dispo() then
    raise exception 'kein Zugriff';
  end if;
  for d in
    select r.id, p.stundenlohn
    from public.driver_service_requests r
    join public.profiles p on p.id = r.driver_id
    where lower(coalesce(r.status, '')) in ('accepted', 'assigned', 'approved')
      and public.stunden_zeitpunkt(r.service_date, r.service_start_time) <= now()
  loop
    minuten := public.dienst_minuten_bisher(d.id);
    stunden := stunden + minuten / 60.0;
    if d.stundenlohn is null then
      if minuten > 0 then ohne_lohn := ohne_lohn + 1; end if;
    else
      kosten := kosten + minuten / 60.0 * d.stundenlohn;
    end if;
  end loop;
  return jsonb_build_object('kosten', round(kosten, 2), 'stunden', round(stunden, 2), 'dienste_ohne_lohn', ohne_lohn);
end;

