declare
  j record;
  live public.driver_live_locations%rowtype;
  jetzt timestamptz := now();
  luft integer;
  tempo numeric;
  dauer numeric;
  sync_min numeric;
begin
  select x.*,
    coalesce(zo.lat, (x.ext_route_payload->'nach'->>'lat')::float8,
             (x.ext_driver_to_dropoff_payload->'nach'->>'lat')::float8) as z_lat,
    coalesce(zo.lng, (x.ext_route_payload->'nach'->>'lon')::float8, (x.ext_route_payload->'nach'->>'lng')::float8,
             (x.ext_driver_to_dropoff_payload->'nach'->>'lon')::float8) as z_lng
  into j
  from public.jobs x
  left join public.orte zo on zo.id = x.dropoff_ort_id
  where x.id = p_job;
  if not found then return; end if;

  rest_min := null; geschaetzt := false; am_ziel := false;
  if j.driver_id is not null and j.z_lat is not null then
    select * into live from public.driver_live_locations l
    where l.driver_id = j.driver_id
      and coalesce(l.captured_at, l.updated_at) > jetzt - interval '3 minutes'
      and l.lat is not null and l.lng is not null;
    if found then luft := public.trisar_luftlinie_m(live.lat, live.lng, j.z_lat, j.z_lng); end if;
  end if;

  dauer := coalesce(j.ext_route_duration_in_traffic_mins, j.ext_route_duration_mins);
  tempo := case when coalesce(j.ext_route_distance_m, 0) > 0 and coalesce(dauer, 0) > 0
                then least(1500, greatest(200, j.ext_route_distance_m / dauer)) else 500 end;
  sync_min := coalesce(j.ext_driver_to_dropoff_duration_in_traffic_mins, j.ext_driver_to_dropoff_duration_mins);

  if luft is not null and luft <= 150 then
    am_ziel := true; rest_min := 0;
  elsif j.ext_driver_to_dropoff_last_sync_at > jetzt - interval '3 minutes' and sync_min is not null then
    rest_min := greatest(0, round(extract(epoch from j.ext_driver_to_dropoff_last_sync_at
                                  + make_interval(mins => sync_min::int) - jetzt) / 60))::int;
  elsif luft is not null then
    rest_min := ceil(luft * 1.3 / tempo)::int; geschaetzt := true;
  end if;
  return next;
end;

declare
  v public.fahrzeug_verbrauch;
  km numeric;
  l numeric;
  dkm numeric;
  dl numeric;
  skm numeric;
  sl numeric;
  verbrauch numeric;
begin
  km := coalesce(new.oem_mileage_km, new.total_odometer_km);
  l := new.oem_fuel_l;
  if new.imei is null or km is null or l is null then
    new.verbrauch_l_100km := null;
    new.geschaetzte_reichweite_km := null;
    return new;
  end if;

  select * into v from public.fahrzeug_verbrauch where imei = new.imei for update;
  if not found then
    insert into public.fahrzeug_verbrauch (imei, vin, ref_km, ref_l) values (new.imei, new.vin, km, l);
    verbrauch := null;
  elsif new.vin is not null and v.vin is not null and new.vin <> v.vin then
    -- Tracker steckt in einem anderen Auto: alles vergessen.
    update public.fahrzeug_verbrauch
      set vin = new.vin, ref_km = km, ref_l = l, summe_km = 0, summe_l = 0, l_100km = null, updated_at = now()
      where imei = new.imei;
    verbrauch := null;
  else
    dkm := km - v.ref_km;
    dl := v.ref_l - l;
    verbrauch := v.l_100km;
    if dkm < 0 or dkm > 2000 then
      -- Tacho zurueck oder riesiger Sprung: anderes Auto, neu lernen.
      update public.fahrzeug_verbrauch
        set vin = coalesce(new.vin, vin), ref_km = km, ref_l = l, summe_km = 0, summe_l = 0, l_100km = null, updated_at = now()
        where imei = new.imei;
      verbrauch := null;
    elsif dl < -3 then
      -- Getankt: ab hier neu messen, Gelerntes bleibt.
      update public.fahrzeug_verbrauch
        set vin = coalesce(new.vin, vin), ref_km = km, ref_l = l, updated_at = now()
        where imei = new.imei;
    elsif dkm >= 30 then
      if dl > 0 and dl / dkm * 100 between 2 and 40 then
        skm := v.summe_km + dkm;
        sl := v.summe_l + dl;
        -- Gleitend: hoechstens die letzten 1000 km zaehlen.
        if skm > 1000 then
          sl := sl * 1000 / skm;
          skm := 1000;
        end if;
        verbrauch := case when skm >= 50 then round(sl / skm * 100, 1) end;
        update public.fahrzeug_verbrauch
          set vin = coalesce(new.vin, vin), ref_km = km, ref_l = l, summe_km = skm, summe_l = sl,
              l_100km = verbrauch, updated_at = now()
          where imei = new.imei;
      else
        -- Unplausibel (Tankanzeige springt): Strecke verwerfen.
        update public.fahrzeug_verbrauch
          set ref_km = km, ref_l = l, updated_at = now()
          where imei = new.imei;
      end if;
    end if;
  end if;

  if verbrauch is null then
    select w.verbrauch_l_100km into verbrauch
      from public.vehicles fz join public.fahrzeug_varianten w on w.id = fz.variante_id
     where fz.id = public.trisar_fahrzeug_zum_tracker(new.imei, new.vin);
  end if;
  new.verbrauch_l_100km := verbrauch;
  new.geschaetzte_reichweite_km := case when verbrauch > 0 then round(l / verbrauch * 100) end;
  return new;
end

