declare
  r record;
  jetzt_an boolean;
  vorher boolean;
  anzahl integer := 0;
  bis_wann timestamptz;
begin
  for r in
    select distinct g.user_id as id
      from public.push_geraete g join public.profiles p on p.id = g.user_id
     where g.app = 'fahrer' and coalesce(p.tracking_mode, 'app') <> 'obd'
  loop
    jetzt_an := public.ortung_erlaubt(r.id);
    select z.an into vorher from public.ortung_zustand z where z.driver_id = r.id;
    if vorher is distinct from jetzt_an then
      insert into public.ortung_zustand (driver_id, an, geaendert) values (r.id, jetzt_an, now())
      on conflict (driver_id) do update set an = excluded.an, geaendert = excluded.geaendert;
      if jetzt_an then
        -- Nur wecken, wenn die Arbeitszeit noch mindestens 15 Minuten laeuft (18.11.): ein Dienstende in
        -- 2 Minuten ist kein Arbeitsbeginn.
        select max(f.bis) into bis_wann from public.ortung_fenster(r.id) f where now() >= f.von and now() < f.bis;
        if bis_wann is not null and bis_wann >= now() + interval '15 minutes' then
          perform public.push_melden(r.id, 'fahrer', 'ortung_start', 'Arbeitszeit beginnt',
            'TRISAR sendet deinen Standort jetzt an die Disposition.', jsonb_build_object('ziel', 'liste'));
          anzahl := anzahl + 1;
        end if;
      end if;
    end if;
  end loop;
  return anzahl;
end;

declare
  tag text;
  ort text;
  d uuid;
begin
  if tg_op = 'DELETE' then
    if lower(coalesce(old.status, '')) = 'pending'
       and coalesce(current_setting('trisar.dienst_ersetzt', true), '') <> '1' then
      perform public.push_melden(old.driver_id, 'fahrer', 'dienst_zurueck', 'Dienstanfrage zurückgezogen',
        'Der Dienst am ' || to_char(old.service_date, 'DD.MM.') || ' wurde zurückgezogen.', jsonb_build_object('ziel', 'liste'));
    end if;
    return old;
  end if;

  if coalesce(current_setting('trisar.dienst_antwort', true), '') = '1' then
    return new;
  end if;

  tag := to_char(new.service_date, 'DD.MM.') || ' ' || coalesce(to_char(new.service_start_time, 'HH24:MI'), '?')
    || '–' || coalesce(to_char(new.service_end_time, 'HH24:MI'), '?');
  -- Treffpunkt (13.11.): die Apps speichern ihn vor dem Dienst (gleiche ID), daher hier schon bekannt.
  select nullif(trim(t.name), '') into ort from public.dienst_treffpunkt t where t.dienst_id = new.id;

  if tg_op = 'INSERT' then
    perform public.push_melden(new.driver_id, 'fahrer', 'dienst_neu',
      case when exists (select 1 from public.dienst_aenderung a where a.dienst_id = new.id)
           then 'Dienst geändert' else 'Neue Dienstanfrage' end,
      'Dienst ' || tag || coalesce(', Treffpunkt ' || ort, '') || ', bitte bestätigen.', jsonb_build_object('ziel', 'liste'));
    return new;
  end if;

  if new.service_date is distinct from old.service_date or new.service_start_time is distinct from old.service_start_time
     or new.service_end_time is distinct from old.service_end_time then
    perform public.push_melden(new.driver_id, 'fahrer', 'dienst_geaendert', 'Dienst geändert',
      'Dein Dienst ist jetzt ' || tag || coalesce(', Treffpunkt ' || ort, '') || '.', jsonb_build_object('ziel', 'liste'));
  end if;

  if new.status is distinct from old.status and lower(coalesce(new.status, '')) in ('accepted', 'refused') then
    for d in select public.push_dispo_konten() loop
      perform public.push_melden(d, 'dispo',
        case when lower(new.status) = 'refused' then 'dispo_dienst_abgelehnt' else 'dispo_dienst_angenommen' end,
        case when lower(new.status) = 'refused' then 'Dienst abgelehnt' else 'Dienst bestätigt' end,
        public.push_name(new.driver_id) || ' hat den Dienst '
          || tag || case when lower(new.status) = 'refused' then ' abgelehnt.' else ' bestätigt.' end,
        jsonb_build_object('ziel', 'fahrer', 'user_id', new.driver_id));
    end loop;
  end if;
  return new;
end;

declare
  m record;
  r record;
  anzahl int := 0;
  merker text;
  ort text;
  name text;
  fahrt public.jobs;
begin
  for m in
    select d.*, o.name as o_name from public.dispo_ankunft_melden d
    join public.profiles p on p.id = d.user_id
    left join public.orte o on o.id = d.ort_id
    where d.an and d.lat is not null and d.lng is not null
      and lower(coalesce(p.role, '')) <> 'pruefung'
  loop
    ort := coalesce(nullif(btrim(m.ort_name), ''), m.o_name);
    for r in select * from public.ankunft_liste_fuer(m.user_id) loop
      continue when r.driver_id is null;
      select * into fahrt from public.jobs where id = r.job_id;
      name := public.push_name(r.driver_id);
      if r.angekommen then
        continue when not m.bei_ankunft;
        -- Schon laenger beendete Fahrten nicht nachmelden (z. B. direkt nach dem Einschalten)
        continue when public.trisar_norm_status(fahrt.status) in ('done', 'completed', 'arrived', 'beendet')
          and not exists (select 1 from public.job_status_history h
                          where h.job_id = r.job_id and h.created_at > now() - interval '5 minutes'
                            and public.trisar_norm_status(h.to_status) in ('done', 'completed', 'arrived', 'beendet'));
        merker := 'ankunft_da:' || m.user_id || ':' || r.job_id || ':' || r.art;
        continue when exists (select 1 from public.push_erinnert e where e.schluessel = merker);
        insert into public.push_erinnert (schluessel) values (merker);
        perform public.push_melden(m.user_id, 'dispo', 'dispo_ankunft',
          case when r.art = 'ziel' then 'Angekommen' else 'Zum Abholen da' end,
          name || case when r.art = 'ziel' then ' ist angekommen' else ' ist zum Abholen da' end
            || coalesce(' (' || ort || ')', '') || '. ' || public.push_fahrt_text(fahrt) || '.',
          jsonb_build_object('ziel', 'fahrt', 'job_id', r.job_id, 'driver_id', r.driver_id));
        anzahl := anzahl + 1;
      elsif r.rest_min is not null and (m.minuten = 0 or r.rest_min <= m.minuten) then
        merker := 'ankunft_bald:' || m.user_id || ':' || r.job_id || ':' || r.art;
        continue when exists (select 1 from public.push_erinnert e where e.schluessel = merker);
        insert into public.push_erinnert (schluessel) values (merker);
        perform public.push_melden(m.user_id, 'dispo', 'dispo_ankunft',
          case when m.minuten = 0 then 'Unterwegs zu dir'
               when r.art = 'ziel' then 'Gleich da' else 'Kommt zum Abholen' end,
          name || ' in ' || case when r.geschaetzt then 'ca. ' else '' end || greatest(1, r.rest_min) || ' min bei dir'
            || coalesce(' (' || ort || ')', '') || '. ' || public.push_fahrt_text(fahrt) || '.',
          jsonb_build_object('ziel', 'fahrt', 'job_id', r.job_id, 'driver_id', r.driver_id));
        anzahl := anzahl + 1;
      end if;
    end loop;
  end loop;
  return anzahl;
end;

