declare
  r record;
  d uuid;
  dispo uuid[];
  anzahl int := 0;
  jetzt timestamptz := now();
  heute date := (now() at time zone 'Europe/Berlin')::date;
  merker text;
  minuten int;
begin
  select coalesce(array_agg(k), '{}') into dispo
  from public.push_dispo_konten() k
  where not exists (select 1 from public.profiles p where p.id = k and lower(coalesce(p.role, '')) = 'pruefung');
  if cardinality(dispo) = 0 then return 0; end if;

  -- Fahrer ohne Signal (wie die Dispo-Karte: driver_live_locations.captured_at, 5 min = grau)
  for r in
    select l.driver_id, l.captured_at, public.push_name(l.driver_id) as name
    from public.driver_live_locations l
    join public.profiles p on p.id = l.driver_id
    where l.captured_at is not null
      and l.captured_at < jetzt - interval '5 minutes'
      and lower(coalesce(p.role, '')) not in ('dispo', 'dispatcher', 'admin', 'koordinator', 'coordinator', 'pruefung')
      and (
        -- laufende Fahrt oder offene Fahrt, die in den naechsten 2 Stunden beginnt (oder schon faellig ist)
        exists (
          select 1 from public.jobs j
          where (j.driver_id = l.driver_id or j.id = l.active_job_id
                 or exists (select 1 from public.convoy_assignments c
                            where c.job_id = j.id and c.driver_id = l.driver_id
                              and lower(coalesce(c.response_status, 'pending')) <> 'refused'))
            and j.ride_date between heute - 1 and heute + 1
            and lower(coalesce(j.status, '')) not in ('done', 'completed', 'arrived', 'cancelled', 'canceled', 'storniert', 'refused')
            and not exists (select 1 from public.jobs_archive a where a.job_id = j.id)
            and (
              lower(coalesce(j.status, '')) in ('at_pickup', 'pickup', 'beim_pickup', 'beim pickup', 'in_progress', 'started',
                                                 'unterwegs', 'active', 'ongoing', 'on_trip')
              or (j.etd is not null
                  and (j.ride_date + j.etd) at time zone 'Europe/Berlin' between jetzt - interval '2 hours' and jetzt + interval '2 hours')
            )
        )
        -- oder im angenommenen Dienst
        or exists (
          select 1 from public.driver_service_requests s
          where s.driver_id = l.driver_id
            and lower(coalesce(s.status, '')) = 'accepted'
            and s.service_date between heute - 1 and heute
            and s.service_start_time is not null
            and jetzt >= (s.service_date + s.service_start_time) at time zone 'Europe/Berlin'
            and (s.service_end_time is null
                 or jetzt < (s.service_date + s.service_end_time
                             + case when s.service_end_time <= s.service_start_time then interval '1 day' else interval '0' end)
                            at time zone 'Europe/Berlin')
        )
      )
  loop
    -- Ein Ereignis je Signalverlust: neues Signal und erneuter Verlust melden wieder.
    merker := 'dispo_signal:' || r.driver_id || ':' || extract(epoch from r.captured_at)::bigint;
    continue when exists (select 1 from public.push_erinnert e where e.schluessel = merker);
    insert into public.push_erinnert (schluessel) values (merker);
    minuten := greatest(5, round(extract(epoch from jetzt - r.captured_at) / 60))::int;
    foreach d in array dispo loop
      perform public.push_melden(d, 'dispo', 'dispo_ohne_signal', 'Kein Signal',
        r.name || ' sendet seit ' || case when minuten >= 120 then (minuten / 60) || ' h' else minuten || ' min' end
          || ' kein Signal.',
        jsonb_build_object('ziel', 'fahrer', 'driver_id', r.driver_id));
    end loop;
    anzahl := anzahl + 1;
  end loop;

  -- Fahrten ohne Fahrer, die in hoechstens 30 min beginnen
  for r in
    select j as fahrt, j.id, (j.ride_date + j.etd) at time zone 'Europe/Berlin' as beginn
    from public.jobs j
    where j.ride_date between heute - 1 and heute + 1
      and j.etd is not null
      and j.driver_id is null
      and lower(coalesce(j.status, '')) not in ('done', 'completed', 'arrived', 'cancelled', 'canceled', 'storniert', 'refused')
      and not exists (select 1 from public.jobs_archive a where a.job_id = j.id)
      and not exists (select 1 from public.convoy_assignments c
                      where c.job_id = j.id and c.driver_id is not null
                        and lower(coalesce(c.response_status, 'pending')) <> 'refused')
      and (j.ride_date + j.etd) at time zone 'Europe/Berlin' between jetzt and jetzt + interval '30 minutes'
  loop
    merker := 'dispo_ohne_fahrer:' || r.id;
    continue when exists (select 1 from public.push_erinnert e where e.schluessel = merker);
    insert into public.push_erinnert (schluessel) values (merker);
    foreach d in array dispo loop
      perform public.push_melden(d, 'dispo', 'dispo_ohne_fahrer', 'Fahrt ohne Fahrer',
        'In ' || greatest(1, round(extract(epoch from r.beginn - jetzt) / 60))::int || ' min: '
          || public.push_fahrt_text(r.fahrt) || '. Noch kein Fahrer zugeteilt.',
        jsonb_build_object('ziel', 'fahrt', 'job_id', r.id));
    end loop;
    anzahl := anzahl + 1;
  end loop;

  -- Fahrer kommt zu spaet zum Abholort: letzte Anfahrt (ext_driver_to_pickup_*, hoechstens 15 min alt)
  for r in
    select j as fahrt, j.id, j.driver_id,
           -- Start Zeitraum (13.11.): zu spaet erst nach dem Ende des Zeitraums.
           (j.ride_date + coalesce(j.etd_bis, j.etd)
             + case when j.etd_bis is not null and j.etd_bis < j.etd then interval '1 day' else interval '0' end)
             at time zone 'Europe/Berlin' as beginn,
           j.ext_driver_to_pickup_last_sync_at
             + make_interval(mins => coalesce(j.ext_driver_to_pickup_duration_in_traffic_mins, j.ext_driver_to_pickup_duration_mins)) as ankunft
    from public.jobs j
    where j.ride_date between heute - 1 and heute + 1
      and j.etd is not null
      and j.driver_id is not null
      and coalesce(j.ext_driver_to_pickup_duration_in_traffic_mins, j.ext_driver_to_pickup_duration_mins) is not null
      and j.ext_driver_to_pickup_last_sync_at > jetzt - interval '15 minutes'
      -- nur solange der Fahrer noch zum Gast unterwegs ist
      and lower(coalesce(j.status, '')) not in ('done', 'completed', 'arrived', 'cancelled', 'canceled', 'storniert', 'refused',
                                               'at_pickup', 'pickup', 'beim_pickup', 'beim pickup', 'in_progress', 'started',
                                               'unterwegs', 'ongoing', 'on_trip')
      and not exists (select 1 from public.jobs_archive a where a.job_id = j.id)
      and (j.ride_date + j.etd) at time zone 'Europe/Berlin' between jetzt - interval '1 hour' and jetzt + interval '3 hours'
  loop
    continue when r.ankunft <= r.beginn + interval '5 minutes';
    merker := 'dispo_verspaetet:' || r.id;
    continue when exists (select 1 from public.push_erinnert e where e.schluessel = merker);
    insert into public.push_erinnert (schluessel) values (merker);
    foreach d in array dispo loop
      perform public.push_melden(d, 'dispo', 'dispo_verspaetet', 'Fahrer kommt zu spät',
        public.push_name(r.driver_id) || ' ist etwa ' || round(extract(epoch from r.ankunft - r.beginn) / 60)::int
          || ' min zu spät am Abholort (an ' || to_char(r.ankunft at time zone 'Europe/Berlin', 'HH24:MI') || '). '
          || public.push_fahrt_text(r.fahrt) || '.',
        jsonb_build_object('ziel', 'fahrt', 'job_id', r.id, 'driver_id', r.driver_id));
    end loop;
    anzahl := anzahl + 1;
  end loop;

  return anzahl;
end;

declare
  r record;
  j public.jobs;
  beginn timestamptz;
  f uuid;
  anzahl int := 0;
  jetzt timestamptz := now();
begin
  -- Fahrten mit Startzeitpunkt in Berliner Zeit
  for j in
    select * from public.jobs x
    where x.ride_date between (jetzt at time zone 'Europe/Berlin')::date - 1 and (jetzt at time zone 'Europe/Berlin')::date + 1
      and x.etd is not null
      and lower(coalesce(x.status, '')) not in ('cancelled', 'canceled', 'storniert', 'refused', 'done', 'completed', 'arrived')
  loop
    beginn := (j.ride_date + j.etd) at time zone 'Europe/Berlin';
    -- Noch nicht angenommen, 2 Stunden vorher
    if beginn - jetzt between interval '0 minutes' and interval '120 minutes'
       and j.driver_id is not null
       and lower(coalesce(j.driver_response_status, 'pending')) <> 'accepted'
       and not exists (select 1 from public.push_erinnert e where e.schluessel = 'offen:' || j.id) then
      insert into public.push_erinnert (schluessel) values ('offen:' || j.id);
      perform public.push_melden(j.driver_id, 'fahrer', 'erinnerung_offen', 'Fahrt noch nicht angenommen',
        public.push_fahrt_text(j) || '. Bitte annehmen oder ablehnen.', jsonb_build_object('ziel', 'fahrt', 'job_id', j.id));
      anzahl := anzahl + 1;
    end if;
    -- 30 Minuten vor Beginn
    if beginn - jetzt between interval '0 minutes' and interval '30 minutes'
       and not exists (select 1 from public.push_erinnert e where e.schluessel = 'beginn:' || j.id) then
      insert into public.push_erinnert (schluessel) values ('beginn:' || j.id);
      for f in select public.push_fahrer_der_fahrt(j.id) loop
        perform public.push_melden(f, 'fahrer', 'erinnerung_beginn', 'Fahrt beginnt bald',
          'In ' || greatest(1, round(extract(epoch from beginn - jetzt) / 60))::int || ' min: ' || public.push_fahrt_text(j) || '.',
          jsonb_build_object('ziel', 'fahrt', 'job_id', j.id));
      end loop;
      anzahl := anzahl + 1;
    end if;
  end loop;

  -- Dienstbeginn in 60 Minuten
  for r in
    select s.*, (s.service_date + s.service_start_time) at time zone 'Europe/Berlin' as beginn
    from public.driver_service_requests s
    where lower(coalesce(s.status, '')) = 'accepted'
      and s.service_start_time is not null
      and s.service_date between (jetzt at time zone 'Europe/Berlin')::date - 1 and (jetzt at time zone 'Europe/Berlin')::date + 1
  loop
    if r.beginn - jetzt between interval '0 minutes' and interval '60 minutes'
       and not exists (select 1 from public.push_erinnert e where e.schluessel = 'dienst:' || r.id) then
      insert into public.push_erinnert (schluessel) values ('dienst:' || r.id);
      perform public.push_melden(r.driver_id, 'fahrer', 'erinnerung_dienst', 'Dienst beginnt bald',
        'Dienstbeginn ' || to_char(r.service_start_time, 'HH24:MI') || ' (in '
          || greatest(1, round(extract(epoch from r.beginn - jetzt) / 60))::int || ' min).',
        jsonb_build_object('ziel', 'liste'));
      anzahl := anzahl + 1;
    end if;
  end loop;

  -- Alte Merker und alte Mitteilungen aufraeumen
  delete from public.push_erinnert where erstellt < jetzt - interval '3 days';
  delete from public.push_ausgang where erstellt < jetzt - interval '14 days';
  return anzahl;
end;

declare
  g record;
  r record;
  anzahl int := 0;
  heute date := (now() at time zone 'Europe/Berlin')::date;
  st text;
  name text;
  ziel text;
  v_fahrt constant text[] := array['in_progress', 'unterwegs', 'started', 'on_trip', 'ongoing', 'active'];
  v_beim_gast constant text[] := array['at_pickup', 'pickup', 'beim_pickup', 'beim pickup'];
  v_fertig constant text[] := array['done', 'completed', 'arrived', 'beendet'];
  ereignisse text[];
  e text;
  merker text;
  titel text;
  text_ text;
begin
  for g in
    select fg.user_id, fg.job_id, fg.erstellt, j as fahrt, j.status, j.driver_id, j.dropoff_name, j.dropoff_address
    from public.fahrt_glocke fg
    join public.jobs j on j.id = fg.job_id
    join public.profiles p on p.id = fg.user_id
    where j.ride_date between heute - 1 and heute + 1
      and j.driver_id is not null
      and lower(coalesce(p.role, '')) <> 'pruefung'
      and not exists (select 1 from public.jobs_archive a where a.job_id = j.id)
  loop
    st := public.trisar_norm_status(g.status);
    name := public.push_name(g.driver_id);
    ziel := coalesce(nullif(btrim(split_part(g.dropoff_name, ',', 1)), ''),
                     nullif(btrim(split_part(g.dropoff_address, ',', 1)), ''), 'Ziel');
    select * into r from public.fahrt_ziel_rest(g.job_id);
    ereignisse := '{}';

    if st = any (v_fertig) then
      -- nur melden, wenn die Fahrt nach dem Glocke-Setzen (oder gerade eben) beendet wurde
      if exists (select 1 from public.job_status_history h
                 where h.job_id = g.job_id and public.trisar_norm_status(h.to_status) = any (v_fertig)
                   and h.created_at > least(g.erstellt, now() - interval '5 minutes')) then
        ereignisse := array['da'];
      end if;
    elsif st = any (v_fahrt) then
      if r.am_ziel then
        ereignisse := array['da'];
      else
        ereignisse := array['unterwegs'];
        if r.rest_min is not null and r.rest_min <= 5 then ereignisse := ereignisse || 'bald'::text; end if;
      end if;
    elsif st = any (v_beim_gast) then
      ereignisse := array['gast'];
    end if;

    foreach e in array ereignisse loop
      merker := 'glocke_' || e || ':' || g.user_id || ':' || g.job_id;
      continue when exists (select 1 from public.push_erinnert x where x.schluessel = merker);
      -- "angekommen" schliesst die anderen ab, damit danach nichts mehr nachkommt
      if e = 'da' then
        insert into public.push_erinnert (schluessel) values
          ('glocke_unterwegs:' || g.user_id || ':' || g.job_id),
          ('glocke_bald:' || g.user_id || ':' || g.job_id)
        on conflict do nothing;
      end if;
      insert into public.push_erinnert (schluessel) values (merker) on conflict do nothing;
      if e = 'gast' then
        titel := 'Beim Gast';
        text_ := name || ' ist beim Gast. ' || public.push_fahrt_text(g.fahrt) || '.';
      elsif e = 'unterwegs' then
        titel := 'Mit Gast unterwegs';
        text_ := name || ' ist mit dem Gast unterwegs nach ' || ziel
          || case when r.rest_min is not null
                  then ', an ' || case when r.geschaetzt then 'ca. ' else '' end
                       || to_char((now() + make_interval(mins => r.rest_min)) at time zone 'Europe/Berlin', 'HH24:MI')
                  else '' end || '.';
      elsif e = 'bald' then
        titel := 'Gleich am Ziel';
        text_ := name || ' ist in ' || case when r.geschaetzt then 'ca. ' else '' end
          || greatest(1, r.rest_min) || ' min am Ziel (' || ziel || ').';
      else
        titel := 'Angekommen';
        text_ := name || ' ist am Ziel angekommen (' || ziel || ').';
      end if;
      perform public.push_melden(g.user_id, 'dispo', 'dispo_fahrt_glocke', titel, text_,
        jsonb_build_object('ziel', 'fahrt', 'job_id', g.job_id, 'driver_id', g.driver_id));
      anzahl := anzahl + 1;
    end loop;
  end loop;
  return anzahl;
end;

begin
  if auth.uid() is null or coalesce(p_token, '') = '' then
    return;
  end if;
  insert into public.push_geraete (token, user_id, plattform, app, aktualisiert)
  values (p_token, auth.uid(), p_plattform, p_app, now())
  on conflict (token) do update
    set user_id = excluded.user_id, plattform = excluded.plattform, app = excluded.app, aktualisiert = now();
end;

declare
  fahrt text;
  daten jsonb;
  f uuid;
  d uuid;
  aenderungen text[] := '{}';
  alt_s jsonb;
  neu_s jsonb;
  alt_eta timestamptz;
  neu_eta timestamptz;
  flug text;
  status_neu text;
  status_alt text;
  storno boolean;
begin
  fahrt := public.push_fahrt_text(new);
  daten := jsonb_build_object('ziel', 'fahrt', 'job_id', new.id);

  if tg_op = 'INSERT' then
    if new.driver_id is not null then
      perform public.push_melden(new.driver_id, 'fahrer', 'fahrt_neu', 'Neue Fahrt', fahrt || '. Bitte annehmen.', daten);
    end if;
    return new;
  end if;

  storno := lower(coalesce(new.status, '')) in ('cancelled', 'canceled', 'storniert');

  -- Fahrer gewechselt
  if new.driver_id is distinct from old.driver_id then
    if new.driver_id is not null and not storno then
      perform public.push_melden(new.driver_id, 'fahrer', 'fahrt_neu', 'Neue Fahrt', fahrt || '. Bitte annehmen.', daten);
    end if;
    if old.driver_id is not null and lower(coalesce(new.status, '')) <> 'refused' then
      perform public.push_melden(old.driver_id, 'fahrer', 'fahrt_entzogen', 'Fahrt entzogen',
        fahrt || ' ist dir nicht mehr zugeteilt.', jsonb_build_object('ziel', 'liste'));
    end if;
  end if;

  -- Storniert
  if storno and lower(coalesce(old.status, '')) not in ('cancelled', 'canceled', 'storniert') then
    for f in select public.push_fahrer_der_fahrt(new.id) loop
      perform public.push_melden(f, 'fahrer', 'fahrt_storniert', 'Fahrt storniert', fahrt || ' wurde storniert.',
        jsonb_build_object('ziel', 'liste'));
    end loop;
    return new;
  end if;

  -- Fahrdaten geaendert. Eine reine ETD-Verschiebung durch den Flugabgleich meldet der Flug-Teil.
  if new.ride_date is distinct from old.ride_date then aenderungen := array_append(aenderungen, 'Datum'); end if;
  if new.etd is distinct from old.etd
     and not (new.ext_flight_payload is distinct from old.ext_flight_payload) then
    aenderungen := array_append(aenderungen, 'Zeit ' || coalesce(to_char(old.etd, 'HH24:MI'), '–') || ' → ' || coalesce(to_char(new.etd, 'HH24:MI'), '–'));
  end if;
  if new.pickup_name is distinct from old.pickup_name or new.pickup_address is distinct from old.pickup_address then
    aenderungen := array_append(aenderungen, 'Abholort');
  end if;
  if new.dropoff_name is distinct from old.dropoff_name or new.dropoff_address is distinct from old.dropoff_address then
    aenderungen := array_append(aenderungen, 'Ziel');
  end if;
  if new.flight_number is distinct from old.flight_number then aenderungen := array_append(aenderungen, 'Flugnummer'); end if;
  if new.train_number is distinct from old.train_number then aenderungen := array_append(aenderungen, 'Zugnummer'); end if;
  if cardinality(aenderungen) > 0 and new.driver_id is not distinct from old.driver_id then
    for f in select public.push_fahrer_der_fahrt(new.id) loop
      perform public.push_melden(f, 'fahrer', 'fahrt_geaendert', 'Fahrt geändert',
        fahrt || ': ' || array_to_string(aenderungen, ', ') || '.', daten);
    end loop;
  end if;

  -- Gaeste und Merkmale
  if (new.passengers is distinct from old.passengers or new.anonymous_guests is distinct from old.anonymous_guests
      or new.is_vip is distinct from old.is_vip or new.needs_child_seat is distinct from old.needs_child_seat
      or new.needs_accessibility is distinct from old.needs_accessibility or new.needs_luggage is distinct from old.needs_luggage)
     and new.driver_id is not distinct from old.driver_id then
    for f in select public.push_fahrer_der_fahrt(new.id) loop
      perform public.push_melden(f, 'fahrer', 'gaeste_geaendert', 'Gäste geändert',
        fahrt || ': Gäste oder Hinweise (VIP, Kindersitz, Rollstuhl, Gepäck) wurden angepasst.', daten);
    end loop;
  end if;

  -- Anderes Fahrzeug fuer die Fahrt
  if new.vehicle_id is distinct from old.vehicle_id and new.vehicle_id is not null then
    for f in select public.push_fahrer_der_fahrt(new.id) loop
      perform public.push_melden(f, 'fahrer', 'fahrt_fahrzeug', 'Anderes Fahrzeug',
        fahrt || ' jetzt mit ' || coalesce((select v.license_plate from public.vehicles v where v.id = new.vehicle_id), 'anderem Fahrzeug') || '.',
        daten);
    end loop;
  end if;

  -- Flug: Status und erwartete Ankunft
  if new.ext_flight_payload is distinct from old.ext_flight_payload then
    alt_s := coalesce(old.ext_flight_payload -> 'summary', '{}'::jsonb);
    neu_s := coalesce(new.ext_flight_payload -> 'summary', '{}'::jsonb);
    flug := coalesce(nullif(trim(new.flight_number), ''), 'Flug');
    status_alt := upper(coalesce(alt_s ->> 'flight_status_code', ''));
    status_neu := upper(coalesce(neu_s ->> 'flight_status_code', ''));
    if status_neu <> status_alt and status_neu = 'LD' then
      for f in select public.push_fahrer_der_fahrt(new.id) loop
        perform public.push_melden(f, 'fahrer', 'flug_gelandet', flug || ' gelandet', fahrt || '.', daten);
      end loop;
    elsif status_neu <> status_alt and status_neu = 'CD' then
      for f in select public.push_fahrer_der_fahrt(new.id) loop
        perform public.push_melden(f, 'fahrer', 'flug_annulliert', flug || ' annulliert', fahrt || '. Bitte bei der Dispo melden.', daten);
      end loop;
    elsif status_neu <> status_alt and status_neu in ('RT', 'DV') then
      for f in select public.push_fahrer_der_fahrt(new.id) loop
        perform public.push_melden(f, 'fahrer', 'flug_umgeleitet', flug || ' umgeleitet', fahrt || '. Bitte bei der Dispo melden.', daten);
      end loop;
    else
      alt_eta := coalesce(public.push_zeit(alt_s ->> 'estimated_arrival_local'), public.push_zeit(alt_s ->> 'scheduled_arrival_local'));
      neu_eta := coalesce(public.push_zeit(neu_s ->> 'estimated_arrival_local'), public.push_zeit(neu_s ->> 'scheduled_arrival_local'));
      if alt_eta is not null and neu_eta is not null and abs(extract(epoch from neu_eta - alt_eta)) >= 600 then
        for f in select public.push_fahrer_der_fahrt(new.id) loop
          perform public.push_melden(f, 'fahrer', 'flug_zeit',
            flug || case when neu_eta > alt_eta then ' später' else ' früher' end,
            flug || ' landet ' || abs(round(extract(epoch from neu_eta - alt_eta) / 60))::int || ' min '
              || case when neu_eta > alt_eta then 'später' else 'früher' end
              || coalesce(', neue ETD ' || to_char(new.etd, 'HH24:MI'), '') || '. ' || fahrt || '.',
            daten);
        end loop;
      end if;
    end if;
  end if;

  -- Zug: Prognose verschiebt sich um mindestens 10 Minuten
  if new.train_predicted_time is distinct from old.train_predicted_time
     and new.train_predicted_time is not null
     and abs(extract(epoch from new.train_predicted_time - coalesce(old.train_predicted_time, new.train_planned_time, new.train_predicted_time))) >= 600 then
    for f in select public.push_fahrer_der_fahrt(new.id) loop
      perform public.push_melden(f, 'fahrer', 'zug_zeit', coalesce(nullif(trim(new.train_number), ''), 'Zug') || ' verspätet',
        'Neue Ankunft ' || to_char(new.train_predicted_time, 'HH24:MI')
          || coalesce(' (Plan ' || to_char(new.train_planned_time, 'HH24:MI') || ')', '') || '. ' || fahrt || '.',
        daten);
    end loop;
  end if;

  -- Dispo: Antwort des Fahrers
  if new.driver_response_status is distinct from old.driver_response_status
     and lower(coalesce(new.driver_response_status, '')) in ('accepted', 'refused') then
    for d in select public.push_dispo_konten() loop
      if lower(new.driver_response_status) = 'refused' then
        perform public.push_melden(d, 'dispo', 'dispo_abgelehnt', 'Fahrt abgelehnt',
          public.push_name(coalesce(new.refused_by_driver_id, old.driver_id)) || ' hat ' || fahrt || ' abgelehnt'
            || coalesce(': ' || nullif(trim(new.refusal_reason), ''), '') || '.', daten);
      else
        perform public.push_melden(d, 'dispo', 'dispo_angenommen', 'Fahrt angenommen',
          public.push_name(new.driver_id) || ' hat ' || fahrt || ' angenommen.', daten);
      end if;
    end loop;
  end if;

  return new;
end;

declare
  j public.jobs;
  d uuid;
  kolonne boolean;
  wort text;
begin
  select * into j from public.jobs where id = coalesce(new.job_id, old.job_id);
  if j.id is null then return coalesce(new, old); end if;

  -- Nach dem Einfuegen zaehlt die neue Zeile mit, nach dem Loeschen fehlt die alte schon.
  kolonne := (select count(distinct ca.driver_id) from public.convoy_assignments ca where ca.job_id = j.id)
             + case when tg_op = 'DELETE' then 1 else 0 end > 1;
  wort := case when kolonne then 'Kolonnenfahrt' else 'Fahrt' end;

  if tg_op = 'INSERT' then
    if new.driver_id is not null and new.driver_id is distinct from j.driver_id then
      perform public.push_melden(new.driver_id, 'fahrer', 'fahrt_neu', 'Neue ' || wort,
        public.push_fahrt_text(j) || '. Bitte annehmen.', jsonb_build_object('ziel', 'fahrt', 'job_id', j.id));
    end if;
    return new;
  elsif tg_op = 'DELETE' then
    if old.driver_id is not null and old.driver_id is distinct from j.driver_id
       and coalesce(old.response_status, '') <> 'refused' then
      perform public.push_melden(old.driver_id, 'fahrer', 'fahrt_entzogen', 'Fahrt entzogen',
        public.push_fahrt_text(j) || ' ist dir nicht mehr zugeteilt.', jsonb_build_object('ziel', 'liste'));
    end if;
    return old;
  end if;

  if new.response_status is distinct from old.response_status and new.response_status in ('accepted', 'refused') then
    for d in select public.push_dispo_konten() loop
      perform public.push_melden(d, 'dispo',
        case when new.response_status = 'refused' then 'dispo_abgelehnt' else 'dispo_angenommen' end,
        wort || case when new.response_status = 'refused' then ' abgelehnt' else ' angenommen' end,
        public.push_name(new.driver_id) || ' hat ' || public.push_fahrt_text(j)
          || case when new.response_status = 'refused' then ' abgelehnt' || coalesce(': ' || nullif(trim(new.refusal_reason), ''), '') else ' angenommen' end || '.',
        jsonb_build_object('ziel', 'fahrt', 'job_id', j.id));
    end loop;
  end if;
  return new;
end;

begin
  if p_empfaenger is null then return; end if;
  -- Konto gibt es nicht (mehr), z. B. waehrend es geloescht wird.
  if not exists (select 1 from auth.users u where u.id = p_empfaenger) then return; end if;
  -- Eigene Aenderungen nicht melden.
  if auth.uid() is not null and auth.uid() = p_empfaenger then return; end if;
  if exists (select 1 from public.push_einstellungen e where e.user_id = p_empfaenger and p_art = any(e.aus)) then
    return;
  end if;
  insert into public.push_ausgang (user_id, app, art, titel, text, daten)
  values (p_empfaenger, p_app, p_art, p_titel, p_text, coalesce(p_daten, '{}'::jsonb));
end;

declare
  f uuid;
  d uuid;
  absender text;
  kolonne text;
  vorschau text;
begin
  if new.target_type <> 'group' or new.target_id is null then return new; end if;
  absender := coalesce(public.push_name(new.sender_id), 'Jemand');
  kolonne := coalesce((select nullif(trim(c.name), '') from public.convoys c where c.id = new.target_id), 'Kolonne');
  vorschau := left(regexp_replace(coalesce(new.content, ''), '\s+', ' ', 'g'), 140);

  for f in
    select distinct x.id from (
      select j.driver_id as id from public.jobs j where j.convoy_id = new.target_id
      union
      select c.driver_id from public.convoy_assignments c join public.jobs j on j.id = c.job_id
      where j.convoy_id = new.target_id and coalesce(c.response_status, '') <> 'refused'
    ) x
    where x.id is not null and x.id <> new.sender_id
  loop
    perform public.push_melden(f, 'fahrer', 'chat', kolonne, absender || ': ' || vorschau,
      jsonb_build_object('ziel', 'chat', 'kolonne_id', new.target_id));
  end loop;

  for d in select public.push_dispo_konten() loop
    if d <> new.sender_id then
      perform public.push_melden(d, 'dispo', 'chat', kolonne, absender || ': ' || vorschau,
        jsonb_build_object('ziel', 'chat', 'kolonne_id', new.target_id));
    end if;
  end loop;
  return new;
end;

declare
  j public.jobs;
  f uuid;
begin
  select * into j from public.jobs where id = new.job_id;
  if j.id is null then return new; end if;
  for f in select public.push_fahrer_der_fahrt(j.id) loop
    perform public.push_melden(f, 'fahrer', 'notiz', 'Neue Notiz',
      left(regexp_replace(coalesce(new.note_text, ''), '\s+', ' ', 'g'), 160) || ' · ' || public.push_fahrt_text(j),
      jsonb_build_object('ziel', 'fahrt', 'job_id', j.id));
  end loop;
  return new;
end;

begin
  if new.vehicle_id is distinct from old.vehicle_id and new.vehicle_id is not null then
    perform public.push_melden(new.id, 'fahrer', 'fahrzeug_neu', 'Neues Fahrzeug',
      'Dir ist jetzt ' || coalesce((select v.license_plate from public.vehicles v where v.id = new.vehicle_id), 'ein neues Fahrzeug')
        || ' zugewiesen.', jsonb_build_object('ziel', 'fahrzeug'));
  end if;
  return new;
end;

declare
  d uuid;
begin
  for d in select public.push_dispo_konten() loop
    perform public.push_melden(d, 'dispo', 'dispo_schaden', 'Schaden gemeldet',
      coalesce((select v.license_plate from public.vehicles v where v.id = new.vehicle_id), 'Fahrzeug')
        || coalesce(': ' || nullif(trim(new.part_name), ''), '')
        || coalesce(' (' || public.push_name(new.reported_by) || ')', '')
        || coalesce(' – ' || left(nullif(trim(new.description), ''), 120), ''),
      jsonb_build_object('ziel', 'fahrzeug', 'vehicle_id', new.vehicle_id));
  end loop;
  return new;
end;

declare
  k uuid;
  tag text := to_char(new.datum, 'DD.MM.');
  zeit text := to_char(make_interval(mins => new.arbeits_min), 'HH24:MI') || ' h';
  name text := coalesce(public.push_name(new.driver_id), 'Fahrer');
  geaendert boolean := tg_op = 'INSERT' or old.status is distinct from new.status
    or old.beginn <> new.beginn or old.ende <> new.ende or old.pause_min <> new.pause_min;
begin
  if not geaendert then
    return new;
  end if;
  if new.status = 'eingereicht' then
    for k in select public.push_dispo_konten() loop
      perform public.push_melden(k, 'dispo', 'dispo_stunden', 'Stunden bestätigen',
        name || ', ' || tag || ': ' || zeit || case when new.angepasst then ' (bearbeitet)' else '' end,
        jsonb_build_object('ziel', 'fahrer', 'driver_id', new.driver_id));
    end loop;
  elsif new.status = 'dispo_geaendert' then
    perform public.push_melden(new.driver_id, 'fahrer', 'fahrer_stunden', 'Dispo hat deine Stunden geändert',
      tag || ': ' || to_char(new.beginn at time zone 'Europe/Berlin', 'HH24:MI') || '–'
        || to_char(new.ende at time zone 'Europe/Berlin', 'HH24:MI') || ', ' || zeit || '. Bitte bestätigen.',
      jsonb_build_object('ziel', 'liste'));
  elsif tg_op = 'UPDATE' and new.status = 'bestaetigt' and old.status = 'dispo_geaendert' then
    for k in select public.push_dispo_konten() loop
      perform public.push_melden(k, 'dispo', 'dispo_stunden', 'Stunden bestätigt',
        name || ' hat die geänderten Stunden vom ' || tag || ' bestätigt (' || zeit || ').',
        jsonb_build_object('ziel', 'fahrer', 'driver_id', new.driver_id));
    end loop;
  elsif tg_op = 'UPDATE' and new.status in ('bestaetigt', 'zurueckgewiesen') and old.status is distinct from new.status then
    perform public.push_melden(new.driver_id, 'fahrer', 'fahrer_stunden',
      case when new.status = 'bestaetigt' then 'Stunden bestätigt' else 'Stunden zurückgegeben' end,
      tag || coalesce(': ' || nullif(trim(new.dispo_notiz), ''), ''),
      jsonb_build_object('ziel', 'verlauf'));
  end if;
  return new;
end;

declare
  d record;
  titel text;
  text_ text;
begin
  if tg_op = 'DELETE' then
    return old;
  end if;
  -- Umhaengen beim Ersetzen eines Dienstes (trisar_dienst_zusammenfuehren): still.
  if coalesce(current_setting('trisar.dienst_ersetzt', true), '') = '1' then
    return new;
  end if;
  select * into d from public.driver_service_requests where id = new.dienst_id;
  -- Dienst gibt es noch nicht (Treffpunkt vor dem Dienst gespeichert) oder gerade erst angelegt:
  -- die Mitteilung zum Dienst nennt den Ort schon.
  if not found or d.created_at > now() - interval '30 seconds'
     or lower(coalesce(d.status, '')) not in ('pending', 'accepted') then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.name is not distinct from old.name and new.adresse is not distinct from old.adresse
     and new.notiz is not distinct from old.notiz then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.name is not distinct from old.name and new.adresse is not distinct from old.adresse then
    titel := 'Neue Notiz zum Dienst';
    text_ := 'Dienst ' || to_char(d.service_date, 'DD.MM.') || ': ' || left(coalesce(new.notiz, ''), 120);
  else
    titel := 'Treffpunkt für deinen Dienst';
    text_ := 'Dienst ' || to_char(d.service_date, 'DD.MM.') || coalesce(' ab ' || to_char(d.service_start_time, 'HH24:MI'), '')
      || ': Treffpunkt ' || coalesce(nullif(trim(new.name), ''), new.adresse, '?') || '.';
  end if;
  perform public.push_melden(d.driver_id, 'fahrer', 'dienst_treffpunkt', titel, text_, jsonb_build_object('ziel', 'liste'));
  return new;
end;

begin
  if coalesce(p_text, '') = '' then return null; end if;
  return p_text::timestamptz;
exception when others then
  return null;
end;

select case
  when coalesce(p_plan, '') !~ '^\d{1,2}:\d{2}' or coalesce(p_ist, '') !~ '^\d{1,2}:\d{2}' then null
  else (((split_part(p_ist, ':', 1)::int * 60 + left(split_part(p_ist, ':', 2), 2)::int)
        - (split_part(p_plan, ':', 1)::int * 60 + left(split_part(p_plan, ':', 2), 2)::int)
        + 1440 + 720) % 1440) - 720
end;

begin
  new.updated_at := now();
  return new;
end;

declare
  f record;
begin
  select * into f from public.standby_fahrer where standby_id = p_standby and driver_id = auth.uid();
  if not found then
    raise exception 'kein Zugriff';
  end if;
  if p_annehmen then
    update public.standby_fahrer set status = 'accepted', vorher = null, aktualisiert = now()
     where standby_id = p_standby and driver_id = auth.uid();
    return 'accepted';
  end if;
  if f.vorher is null then
    update public.standby_fahrer set status = 'refused', aktualisiert = now()
     where standby_id = p_standby and driver_id = auth.uid();
    return 'refused';
  end if;
  -- Aenderung abgelehnt: fuer diesen Fahrer gelten die alten Zeiten.
  update public.standby_fahrer
     set status = 'accepted', von_eigen = nullif(f.vorher->>'von', '')::time, bis_eigen = nullif(f.vorher->>'bis', '')::time,
         vorher = null, aktualisiert = now()
   where standby_id = p_standby and driver_id = auth.uid();
  return 'zurueckgesetzt';
end;

declare
  f record;
  p record;
  neu text;
begin
  if p_art not in ('gast_drin', 'abgesetzt', 'zurueck') then
    raise exception 'unbekannt';
  end if;
  select * into f from public.standby_fahrer where standby_id = p_standby and driver_id = auth.uid() and status = 'accepted';
  if not found then
    raise exception 'kein Zugriff';
  end if;
  select lat, lng into p from public.driver_live_locations where driver_id = auth.uid();
  neu := case p_art when 'gast_drin' then 'mit_gast' when 'abgesetzt' then 'rueckweg' else 'vor_ort' end;
  update public.standby_fahrer
     set zustand = neu, zustand_seit = now(), aktualisiert = now(),
         max_abstand_m = case when neu = 'mit_gast' then 0 else max_abstand_m end,
         max_lat = case when neu = 'mit_gast' then null else max_lat end,
         max_lng = case when neu = 'mit_gast' then null else max_lng end
   where standby_id = p_standby and driver_id = auth.uid();
  insert into public.standby_ereignis (standby_id, driver_id, art, lat, lng, quelle)
  values (p_standby, auth.uid(), p_art, p.lat, p.lng, 'knopf');
  return neu;
end;

declare
  s record;
  text_ort text;
  k uuid;
begin
  select * into s from public.standby where id = coalesce(new.standby_id, old.standby_id);
  if not found then
    return coalesce(new, old);
  end if;
  text_ort := s.ort_name || ' ' || to_char(s.datum, 'DD.MM.') || ' ' || to_char(s.von, 'HH24:MI') || '–' || to_char(s.bis, 'HH24:MI');
  if tg_op = 'INSERT' then
    perform public.push_melden(new.driver_id, 'fahrer', 'standby_neu', 'Standby-Anfrage', 'Standby ' || text_ort || ', bitte bestätigen.', jsonb_build_object('ziel', 'liste'));
  elsif tg_op = 'DELETE' then
    perform public.push_melden(old.driver_id, 'fahrer', 'standby_zurueck', 'Standby zurückgezogen', 'Standby ' || text_ort || ' wurde zurückgezogen.', jsonb_build_object('ziel', 'liste'));
    return old;
  elsif new.status = 'accepted' and old.vorher is not null and (new.von_eigen is not null or new.bis_eigen is not null) then
    -- Aenderung abgelehnt: fuer diesen Fahrer gelten die alten Zeiten.
    for k in select public.push_dispo_konten() loop
      perform public.push_melden(k, 'dispo', 'dispo_standby_abgelehnt', 'Änderung abgelehnt',
        public.push_name(new.driver_id) || ' hat die Änderung am Standby ' || s.ort_name || ' abgelehnt. Für ihn gilt weiter '
          || to_char(new.von_eigen, 'HH24:MI') || '–' || to_char(new.bis_eigen, 'HH24:MI') || '.',
        jsonb_build_object('ziel', 'fahrer', 'user_id', new.driver_id));
    end loop;
  elsif new.status is distinct from old.status and new.status in ('accepted', 'refused') then
    for k in select public.push_dispo_konten() loop
      perform public.push_melden(k, 'dispo', case when new.status = 'refused' then 'dispo_standby_abgelehnt' else 'dispo_standby_angenommen' end,
        case when new.status = 'refused' then 'Standby abgelehnt' else 'Standby bestätigt' end,
        public.push_name(new.driver_id) || case when new.status = 'refused' then ' hat Standby ' else ' hat Standby ' end || text_ort
          || case when new.status = 'refused' then ' abgelehnt.' else ' bestätigt.' end,
        jsonb_build_object('ziel', 'fahrer', 'user_id', new.driver_id));
    end loop;
  end if;
  return new;
end;

declare
  v_schluessel text;
begin
  select value #>> '{}' into v_schluessel from public.integration_settings where key = 'edge_service_role_key';
  if coalesce(v_schluessel, '') = '' then return; end if;
  perform net.http_post(
    url := 'http://kong:8000/functions/v1/external-sync',
    body := jsonb_build_object('aktion', 'standby_rueckweg', 'standby_id', p_standby, 'driver_id', p_fahrer),
    headers := jsonb_build_object('Content-Type', 'application/json',
                                  'Authorization', 'Bearer ' || v_schluessel,
                                  'apikey', v_schluessel),
    timeout_milliseconds := 30000
  );
end;

declare
  f record;
begin
  for f in
    update public.standby_fahrer s set rueck_sync = now()
     where s.driver_id = new.driver_id and s.zustand = 'rueckweg' and lower(s.status) = 'accepted'
       and (s.rueck_sync is null or s.rueck_sync < now() - interval '45 seconds')
    returning s.standby_id, s.driver_id
  loop
    perform public.standby_rueckweg_rufen(f.standby_id, f.driver_id);
  end loop;
  return null;
end;

begin
  if new.zustand is distinct from old.zustand then
    if new.zustand = 'rueckweg' then
      new.rueck_sync := now();
      perform public.standby_rueckweg_rufen(new.standby_id, new.driver_id);
    else
      new.rueck_ankunft := null;
      new.rueck_minuten := null;
      new.rueck_sync := null;
    end if;
  end if;
  return new;
end;

declare
  r record;
  d double precision;
begin
  if new.lat is null or new.lng is null then
    return null;
  end if;
  for r in
    select f.*, s.lat as s_lat, s.lng as s_lng, s.radius_rein_m, s.radius_raus_m
      from public.standby_fahrer f
      join public.standby s on s.id = f.standby_id
     where f.driver_id = new.driver_id and f.status = 'accepted'
       and now() between public.standby_zeitpunkt(s.datum, coalesce(f.von_eigen, s.von)) - interval '30 minutes'
                     and public.standby_zeitpunkt(s.datum, coalesce(f.bis_eigen, s.bis))
                         + case when coalesce(f.bis_eigen, s.bis) <= coalesce(f.von_eigen, s.von) then interval '1 day' else interval '0' end
                         + interval '30 minutes'
  loop
    d := public.standby_abstand_m(r.s_lat, r.s_lng, new.lat, new.lng);
    if d <= r.radius_rein_m and r.zustand <> 'vor_ort' then
      update public.standby_fahrer set zustand = 'vor_ort', zustand_seit = now(), aktualisiert = now()
       where standby_id = r.standby_id and driver_id = r.driver_id;
      if r.zustand <> 'geplant' then
        insert into public.standby_ereignis (standby_id, driver_id, art, lat, lng) values (r.standby_id, r.driver_id, 'zurueck', new.lat, new.lng);
      end if;
    elsif r.zustand = 'vor_ort' and d > r.radius_raus_m then
      update public.standby_fahrer set zustand = 'mit_gast', zustand_seit = now(), max_abstand_m = d, max_lat = new.lat, max_lng = new.lng, aktualisiert = now()
       where standby_id = r.standby_id and driver_id = r.driver_id;
      insert into public.standby_ereignis (standby_id, driver_id, art, lat, lng) values (r.standby_id, r.driver_id, 'gast_drin', new.lat, new.lng);
    elsif r.zustand = 'mit_gast' then
      if d > coalesce(r.max_abstand_m, 0) then
        update public.standby_fahrer set max_abstand_m = d, max_lat = new.lat, max_lng = new.lng, aktualisiert = now()
         where standby_id = r.standby_id and driver_id = r.driver_id;
      elsif coalesce(r.max_abstand_m, 0) - d > 500 then
        -- Umkehr Richtung Event: am weitesten Punkt wurde abgesetzt.
        update public.standby_fahrer set zustand = 'rueckweg', zustand_seit = now(), aktualisiert = now()
         where standby_id = r.standby_id and driver_id = r.driver_id;
        insert into public.standby_ereignis (standby_id, driver_id, art, lat, lng) values (r.standby_id, r.driver_id, 'abgesetzt', r.max_lat, r.max_lng);
      end if;
    end if;
  end loop;
  return null;
end;

begin
  if new.von is not distinct from old.von and new.bis is not distinct from old.bis
     and new.datum is not distinct from old.datum and new.lat is not distinct from old.lat and new.lng is not distinct from old.lng then
    return new;
  end if;
  new.geaendert := now();
  update public.standby_fahrer f
     set vorher = coalesce(f.vorher, jsonb_build_object('von', to_char(coalesce(f.von_eigen, old.von), 'HH24:MI'),
                                                        'bis', to_char(coalesce(f.bis_eigen, old.bis), 'HH24:MI'),
                                                        'ort_name', old.ort_name, 'datum', old.datum)),
         status = 'pending', von_eigen = null, bis_eigen = null, aktualisiert = now()
   where f.standby_id = new.id and f.status = 'accepted';
  update public.standby_fahrer f set von_eigen = null, bis_eigen = null where f.standby_id = new.id and f.status = 'pending';
  perform public.push_melden(f.driver_id, 'fahrer', 'standby_geaendert', 'Standby geändert',
    'Standby ' || new.ort_name || ' jetzt ' || to_char(new.von, 'HH24:MI') || '–' || to_char(new.bis, 'HH24:MI') || ', bitte bestätigen.',
    jsonb_build_object('ziel', 'liste'))
  from public.standby_fahrer f where f.standby_id = new.id and f.status = 'pending';
  return new;
end;

declare
  n integer;
begin
  update public.stundenzettel
     set status = 'bestaetigt', aktualisiert = now()
   where id = p_zettel and driver_id = auth.uid() and status = 'dispo_geaendert';
  get diagnostics n = row_count;
  if n = 0 then
    raise exception 'Diese Stunden warten nicht auf deine Zustimmung.';
  end if;
end;

declare
  fahrer uuid := coalesce(p_driver, auth.uid());
  heute date := (now() at time zone 'Europe/Berlin')::date;
  ergebnis jsonb := '[]'::jsonb;
  d record;
  z record;
begin
  if fahrer <> auth.uid() and not public.ist_dispo() then
    raise exception 'kein Zugriff';
  end if;
  -- Stundenerfassung fuer diesen Fahrer aus: der Fahrer-App (fragt ohne p_driver) nichts zeigen.
  -- Die Dispo fragt immer mit p_driver und sieht weiter alles.
  if p_driver is null and not public.stundenerfassung_an(fahrer) then
    return '[]'::jsonb;
  end if;
  for d in
    select * from public.driver_service_requests
    where driver_id = fahrer
      and lower(coalesce(status, '')) in ('accepted', 'assigned', 'approved')
      and service_date <= heute
      and service_date >= heute - p_tage
    order by service_date desc, service_start_time desc
  loop
    select * into z from public.stundenzettel where dienst_id = d.id;
    ergebnis := ergebnis || jsonb_build_object(
      'dienst', jsonb_build_object('id', d.id, 'datum', d.service_date,
        'beginn', to_char(d.service_start_time, 'HH24:MI'), 'ende', to_char(d.service_end_time, 'HH24:MI'),
        'pausen', coalesce((select dp.pausen from public.dienst_pausen dp where dp.dienst_id = d.id), '[]'::jsonb)),
      'vorschlag', public.stunden_vorschlag_server(d.id),
      'zettel', case when z.id is null then null else to_jsonb(z) end,
      -- Standby am Event-Ort an diesem Tag (Vermerk "BMW Welt 18:00–23:00").
      'standby', coalesce((select jsonb_agg(jsonb_build_object('ort', s.ort_name,
          'von', to_char(coalesce(sf.von_eigen, s.von), 'HH24:MI'), 'bis', to_char(coalesce(sf.bis_eigen, s.bis), 'HH24:MI'))
          order by s.von)
        from public.standby_fahrer sf join public.standby s on s.id = sf.standby_id
        where sf.driver_id = fahrer and sf.status = 'accepted' and s.datum = d.service_date), '[]'::jsonb),
      -- Erfassen erst, wenn der Dienst vorbei ist. Ohne Dienstende ist er NICHT vorbei (13.11.):
      -- erst wenn die Dispo das Ende schickt, kommt die Stundenerfassung (vorher galt coalesce(.., now())).
      'vorbei', d.service_end_time is not null and coalesce(public.stunden_zeitpunkt(d.service_date, d.service_end_time) +
                  case when d.service_end_time <= d.service_start_time then interval '1 day' else interval '0' end, 'infinity'::timestamptz) <= now()
    );
  end loop;
  return ergebnis;
end;

begin
  if not exists (select 1 from public.driver_service_requests d where d.id = p_dienst_id
                 and (d.driver_id = auth.uid() or public.ist_dispo())) then
    raise exception 'kein Zugriff';
  end if;
  return public.stunden_vorschlag_server(p_dienst_id);
end;

declare
  d record;
  dienst_beginn timestamptz;
  dienst_ende timestamptz;
  fahrten jsonb := '[]'::jsonb;
  f record;
  f_start timestamptz;
  f_ende timestamptz;
  f_genau boolean;
  erster timestamptz;
  letzter timestamptz;
  beginn timestamptz;
  ende timestamptz;
  p jsonb;
  pausen jsonb := '[]'::jsonb;
  p_von timestamptz;
  p_bis timestamptz;
  pause_min integer := 0;
  ende_je_fahrt jsonb := '{}'::jsonb;
begin
  select * into d from public.driver_service_requests where id = p_dienst_id;
  if not found then return null; end if;

  dienst_beginn := public.stunden_zeitpunkt(d.service_date, d.service_start_time);
  dienst_ende := public.stunden_zeitpunkt(d.service_date, d.service_end_time);
  if dienst_ende is not null and dienst_beginn is not null and dienst_ende <= dienst_beginn then
    dienst_ende := dienst_ende + interval '1 day';  -- Nachtdienst
  end if;

  for f in
    select j.* from public.jobs j
    where j.driver_id = d.driver_id
      and j.ride_date = d.service_date
      and lower(coalesce(j.status, '')) not in ('cancelled', 'canceled', 'refused', 'storniert', 'stoniert')
    order by j.etd nulls last
  loop
    f_genau := true;
    select min(h.captured_at) into f_start from public.driver_location_history h where h.job_id = f.id;
    if f_start is null then
      select min(s.created_at) into f_start from public.job_status_history s
      where s.job_id = f.id and lower(s.to_status) in ('at_pickup', 'pickup', 'beim_pickup', 'in_progress', 'unterwegs', 'started', 'on_trip', 'ongoing', 'active');
    end if;
    if f_start is null then
      f_genau := false;
      f_start := public.stunden_zeitpunkt(f.ride_date, f.etd) - make_interval(mins => coalesce(f.ext_driver_to_pickup_duration_mins, 0));
    end if;

    select min(s.created_at) into f_ende from public.job_status_history s
    where s.job_id = f.id and lower(s.to_status) in ('done', 'completed', 'arrived', 'beendet');
    if f_ende is null then
      select max(h.captured_at) into f_ende from public.driver_location_history h where h.job_id = f.id;
    end if;
    if f_ende is null or f_ende <= f_start then
      f_genau := false;
      f_ende := public.stunden_zeitpunkt(f.ride_date, f.etd) + make_interval(mins => coalesce(f.ext_route_duration_mins, 30));
    end if;

    if f_start is not null then
      erster := least(coalesce(erster, f_start), f_start);
      letzter := greatest(coalesce(letzter, f_ende), f_ende);
    end if;
    ende_je_fahrt := ende_je_fahrt || jsonb_build_object(f.id::text, f_ende);
    fahrten := fahrten || jsonb_build_object(
      'id', f.id, 'zeit', to_char(f.etd, 'HH24:MI'),
      'gaeste', coalesce(array_to_string(f.passengers, ', '), ''),
      'von', coalesce(f.pickup_name, f.pickup_address), 'nach', coalesce(f.dropoff_name, f.dropoff_address),
      'start', f_start, 'ende', f_ende, 'genau', f_genau, 'status', f.status);
  end loop;

  beginn := least(dienst_beginn, erster);
  ende := greatest(dienst_ende, letzter);
  if beginn is null then beginn := coalesce(dienst_beginn, erster); end if;
  if ende is null then ende := coalesce(dienst_ende, letzter); end if;

  for p in select * from jsonb_array_elements(coalesce((select dp.pausen from public.dienst_pausen dp where dp.dienst_id = d.id), '[]'::jsonb))
  loop
    p_von := null; p_bis := null;
    if p->>'art' = 'fest' then
      p_von := public.stunden_zeitpunkt(d.service_date, (p->>'von')::time);
      p_bis := public.stunden_zeitpunkt(d.service_date, (p->>'bis')::time);
      if p_bis <= p_von then p_bis := p_bis + interval '1 day'; end if;
    elsif p->>'art' = 'nach_fahrt' and ende_je_fahrt ? (p->>'job_id') then
      p_von := (ende_je_fahrt->>(p->>'job_id'))::timestamptz + make_interval(mins => coalesce((p->>'nach_min')::int, 0));
      p_bis := p_von + make_interval(mins => coalesce((p->>'dauer_min')::int, 0));
    end if;
    if p_von is not null and p_bis is not null and beginn is not null then
      -- Nur der Teil innerhalb der Arbeitszeit zaehlt.
      p_von := greatest(p_von, beginn);
      p_bis := least(p_bis, ende);
      if p_bis > p_von then
        pausen := pausen || jsonb_build_object('von', p_von, 'bis', p_bis, 'art', p->>'art');
        pause_min := pause_min + round(extract(epoch from (p_bis - p_von)) / 60)::int;
      end if;
    end if;
  end loop;

  return jsonb_build_object(
    'dienst_id', d.id,
    'datum', d.service_date,
    'dienst_beginn', dienst_beginn,
    'dienst_ende', dienst_ende,
    'beginn', beginn,
    'ende', ende,
    'pausen', pausen,
    'pause_min', pause_min,
    'arbeits_min', case when beginn is null or ende is null then 0
                        else greatest(0, round(extract(epoch from (ende - beginn)) / 60)::int - pause_min) end,
    'fahrten', fahrten
  );
end;

declare
  v jsonb := public.stunden_vorschlag_genau(p_dienst_id);
  beginn timestamptz;
  ende timestamptz;
  pause_min integer := 0;
  arbeits integer;
  p jsonb;
  lang jsonb := '[]'::jsonb;
  dauer integer;
begin
  if v is null then return null; end if;
  beginn := public.stunden_halbe_ab((v->>'beginn')::timestamptz);
  ende := public.stunden_halbe_auf((v->>'ende')::timestamptz);
  for p in select * from jsonb_array_elements(coalesce(v->'pausen', '[]'::jsonb)) loop
    dauer := round(extract(epoch from ((p->>'bis')::timestamptz - (p->>'von')::timestamptz)) / 60)::int;
    if dauer >= 180 then
      lang := lang || p;
      pause_min := pause_min + dauer;
    end if;
  end loop;
  pause_min := (floor(pause_min / 30.0) * 30)::int;
  v := jsonb_set(v, '{pausen}', lang);
  arbeits := case when beginn is null or ende is null then 0
                  else greatest(0, (extract(epoch from (ende - beginn)) / 60)::int - pause_min) end;
  return v || jsonb_build_object(
    'beginn', beginn, 'ende', ende, 'pause_min', pause_min, 'arbeits_min', arbeits,
    'beginn_genau', v->'beginn', 'ende_genau', v->'ende');
end;

begin
  -- Server (service_role, ohne Konto) und Dispo duerfen, sonst bleibt der alte Wert.
  if new.stundenlohn is distinct from old.stundenlohn and auth.uid() is not null and not public.ist_dispo() then
    new.stundenlohn := old.stundenlohn;
  end if;
  return new;
end;

declare
  t public.obd_tracker%rowtype;
  v_spannung numeric := new.ext_voltage_v;
  v_kmh numeric := nullif(new.raw_io ->> '24', '')::numeric;
  v_zeit timestamptz := coalesce(new.captured_at, now());
  v_erkannt text;
begin
  select * into t from public.obd_tracker where imei = new.imei;
  if not found then
    return new;
  end if;
  if coalesce(v_kmh, 0) > 5 or coalesce(new.obd_speed_kph, 0) > 5 or t.letzte_fahrt_am is null then
    update public.obd_tracker set letzte_fahrt_am = v_zeit where imei = new.imei;
    t.letzte_fahrt_am := v_zeit;
  end if;
  if t.anschluss_quelle = 'hand' then
    return new;
  end if;

  if nullif(btrim(coalesce(new.vin, '')), '') is not null or coalesce(new.rpm, 0) > 0 then
    v_erkannt := 'obd';
  elsif v_spannung is not null and v_spannung < 3 then
    v_erkannt := 'usbc';
  elsif v_spannung is not null and v_spannung > 11 and coalesce(v_kmh, 0) <= 5
        and v_zeit - t.letzte_fahrt_am > interval '30 minutes' then
    v_erkannt := 'obd';
  end if;

  if v_erkannt is not null and v_erkannt is distinct from t.anschluss then
    perform public.tracker_anschluss_setzen(new.imei, v_erkannt, 'auto');
  end if;
  return new;
end;

declare
  v_schlaf text;
begin
  if p_anschluss not in ('usbc', 'obd') then
    raise exception 'anschluss muss usbc oder obd sein';
  end if;
  v_schlaf := case when p_anschluss = 'obd' then (case when public.tracker_im_dienst(p_imei) then 'online' else 'tief' end) end;
  update public.obd_tracker_befehl
     set status = 'ersetzt'
   where imei = p_imei and art in ('anschluss', 'schlaf') and status in ('offen', 'gesendet');
  insert into public.obd_tracker_befehl (imei, befehl, art)
  values (p_imei, public.obd_anschluss_befehl(p_anschluss, v_schlaf), 'anschluss');
  update public.obd_tracker
     set anschluss = p_anschluss,
         anschluss_quelle = coalesce(p_quelle, 'auto'),
         anschluss_status = 'wartet',
         anschluss_geaendert_am = now(),
         anschluss_quittung_am = null,
         schlaf = v_schlaf
   where imei = p_imei;
end;

begin
  if not public.ist_dispo() then
    raise exception 'nur Disposition';
  end if;
  perform public.tracker_anschluss_setzen(p_imei, p_anschluss, 'hand');
end;

declare
  r record;
  v_soll text;
  anzahl integer := 0;
begin
  for r in select imei, schlaf from public.obd_tracker where anschluss = 'obd' loop
    v_soll := case when public.tracker_im_dienst(r.imei) then 'online' else 'tief' end;
    if v_soll is distinct from r.schlaf then
      update public.obd_tracker_befehl
         set status = 'ersetzt'
       where imei = r.imei and art = 'schlaf' and status in ('offen', 'gesendet');
      insert into public.obd_tracker_befehl (imei, befehl, art)
      values (r.imei, 'setparam 102:' || case when v_soll = 'online' then '3' else '2' end, 'schlaf');
      update public.obd_tracker set schlaf = v_soll where imei = r.imei;
      anzahl := anzahl + 1;
    end if;
  end loop;
  return anzahl;
end;

begin
  new.updated_at = now();
  return new;
end;

begin
  perform public.refresh_driver_activity_states();
  return null;
end;

declare
  o public.orte%rowtype;
  s public.orte_standard%rowtype;
begin
  select * into s from public.orte_standard limit 1;
  lat := coalesce((p_job.ext_route_payload->'von'->>'lat')::double precision,
                  (p_job.ext_driver_to_pickup_payload->'nach'->>'lat')::double precision);
  lng := coalesce((p_job.ext_route_payload->'von'->>'lon')::double precision,
                  (p_job.ext_route_payload->'von'->>'lng')::double precision,
                  (p_job.ext_driver_to_pickup_payload->'nach'->>'lon')::double precision);
  if p_job.pickup_ort_id is not null then
    select * into o from public.orte where id = p_job.pickup_ort_id;
  elsif lat is not null then
    select x.* into o from public.orte x
     where public.trisar_luftlinie_m(trisar_abholpunkt.lat, trisar_abholpunkt.lng, x.lat, x.lng) <= x.radius_raus_m
     order by public.trisar_luftlinie_m(trisar_abholpunkt.lat, trisar_abholpunkt.lng, x.lat, x.lng) limit 1;
  end if;
  if o.id is not null then
    lat := o.lat;
    lng := o.lng;
  end if;
  rein_m := coalesce(o.radius_rein_m, s.radius_rein_m, public.trisar_get_setting_int('status_pickup_enter_radius_m', 50));
  raus_m := greatest(coalesce(o.radius_raus_m, s.radius_raus_m, public.trisar_get_setting_int('status_pickup_exit_radius_m', 100)), rein_m + 1);
  return next;
end;

begin
  if lower(coalesce(new.status, 'pending')) <> 'refused' then
    perform public.trisar_dienst_zusammenfuehren(new.id, new.driver_id, new.service_date);
  end if;
  return null;
end;

declare
  alt record;
  stand jsonb;
begin
  if lower(coalesce(new.status, 'pending')) = 'refused' then
    return new;
  end if;
  select * into alt from public.driver_service_requests
   where driver_id = new.driver_id and service_date = new.service_date
     and lower(coalesce(status, '')) <> 'refused'
   order by created_at desc
   limit 1;
  if found then
    new.service_start_time := coalesce(new.service_start_time, alt.service_start_time);
    new.service_end_time := coalesce(new.service_end_time, alt.service_end_time);
    if lower(coalesce(new.status, 'pending')) = 'pending' and new.id is not null then
      if lower(coalesce(alt.status, '')) = 'accepted' then
        stand := public.trisar_dienst_stand(alt.id);
      else
        -- Noch offene Aenderung wird erneut geaendert: Vergleich bleibt der angenommene Stand.
        select a.vorher into stand from public.dienst_aenderung a where a.dienst_id = alt.id;
      end if;
      if stand is not null then
        insert into public.dienst_aenderung (dienst_id, vorher) values (new.id, stand)
        on conflict (dienst_id) do update set vorher = excluded.vorher, erstellt = now();
      end if;
    end if;
  end if;
  return new;
end;

declare
  l record;
begin
  if lower(coalesce(new.status, '')) = 'refused' then
    return null;
  end if;
  for l in
    select df.* from public.dienstende_fahrt df
      join public.jobs j on j.id = df.job_id
     where df.driver_id = new.driver_id
       and new.service_date in (j.ride_date, j.ride_date - 1)
       and (df.dienst_id is null or not exists (select 1 from public.driver_service_requests s where s.id = df.dienst_id))
  loop
    if new.service_end_time is null or new.service_end_time = l.ende_gesetzt then
      update public.dienstende_fahrt set dienst_id = new.id, aktualisiert = now()
       where job_id = l.job_id and driver_id = l.driver_id;
      if new.service_end_time is null then
        update public.driver_service_requests set service_end_time = l.ende_gesetzt where id = new.id;
      end if;
    else
      delete from public.dienstende_fahrt where job_id = l.job_id and driver_id = l.driver_id;
    end if;
  end loop;
  -- Fahrten mit "Danach Dienstende", die noch keinen Dienst hatten.
  for l in
    select j.id from public.jobs j
     where j.danach_dienstende
       and (j.driver_id = new.driver_id
            or exists (select 1 from public.convoy_assignments ca where ca.job_id = j.id and ca.driver_id = new.driver_id))
       and new.service_date in (j.ride_date, j.ride_date - 1)
       and not exists (select 1 from public.dienstende_fahrt df where df.job_id = j.id and df.driver_id = new.driver_id)
  loop
    perform public.trisar_dienstende_fahrt_anwenden(l.id);
  end loop;
  return null;
exception when others then
  raise warning 'danach_dienstende dienst %: %', new.id, sqlerrm;
  return null;
end;

declare
  d record;
  alt jsonb;
  neu jsonb;
  v_id uuid;
begin
  -- Beim Zusammenfuehren (neue Zeile ersetzt alte) oder beim Zuruecksetzen nach Ablehnen nichts tun.
  if coalesce(current_setting('trisar.dienst_ersetzt', true), '') = '1'
     or coalesce(current_setting('trisar.dienst_antwort', true), '') = '1' then
    return null;
  end if;
  v_id := case when tg_op = 'DELETE' then old.dienst_id else new.dienst_id end;
  alt := case when tg_op = 'INSERT' then '[]'::jsonb else coalesce(old.pausen, '[]'::jsonb) end;
  neu := case when tg_op = 'DELETE' then '[]'::jsonb else coalesce(new.pausen, '[]'::jsonb) end;
  if alt = neu then
    return null;
  end if;
  select * into d from public.driver_service_requests r where r.id = v_id;
  if not found or lower(coalesce(d.status, '')) <> 'accepted' then
    return null;
  end if;
  insert into public.dienst_aenderung (dienst_id, vorher)
  values (d.id, jsonb_build_object('start', to_char(d.service_start_time, 'HH24:MI'),
                                   'ende', to_char(d.service_end_time, 'HH24:MI'), 'pausen', alt))
  on conflict (dienst_id) do update set vorher = excluded.vorher, erstellt = now();
  -- Status ohne Push "Dienst geändert" (die Zeiten bleiben gleich), eigene Meldung dazu.
  update public.driver_service_requests set status = 'pending' where id = d.id;
  perform public.push_melden(d.driver_id, 'fahrer', 'dienst_geaendert', 'Pause geändert',
    'Deine Pause am ' || to_char(d.service_date, 'DD.MM.') || ' wurde geändert, bitte bestätigen.',
    jsonb_build_object('ziel', 'liste'));
  return null;
end;

declare
  alt record;
begin
  perform set_config('trisar.dienst_ersetzt', '1', true);
  for alt in
    select * from public.driver_service_requests
     where driver_id = p_fahrer and service_date = p_tag and id <> p_neu_id
       and lower(coalesce(status, '')) <> 'refused'
  loop
    -- Pausen: die neue Zeile behaelt ihre eigenen, sonst die des alten Dienstes.
    if exists (select 1 from public.dienst_pausen where dienst_id = alt.id) then
      if exists (select 1 from public.dienst_pausen where dienst_id = p_neu_id) then
        delete from public.dienst_pausen where dienst_id = alt.id;
      else
        update public.dienst_pausen set dienst_id = p_neu_id where dienst_id = alt.id;
      end if;
    end if;
    -- Treffpunkt und Notiz (13.11.): wie Pausen, die neue Zeile behaelt ihre eigenen, sonst die alten.
    if exists (select 1 from public.dienst_treffpunkt where dienst_id = alt.id) then
      if exists (select 1 from public.dienst_treffpunkt where dienst_id = p_neu_id) then
        delete from public.dienst_treffpunkt where dienst_id = alt.id;
      else
        update public.dienst_treffpunkt set dienst_id = p_neu_id where dienst_id = alt.id;
      end if;
    end if;
    -- Stundenzettel: zum neuen Dienst, wenn der noch keinen hat.
    if not exists (select 1 from public.stundenzettel where dienst_id = p_neu_id) then
      update public.stundenzettel set dienst_id = p_neu_id where dienst_id = alt.id;
    end if;
    delete from public.dienst_aenderung where dienst_id = alt.id;
    delete from public.driver_service_requests where id = alt.id;
  end loop;
  perform set_config('trisar.dienst_ersetzt', '', true);
end;

declare
  j public.jobs%rowtype;
  v_weg constant text[] := array['cancelled', 'canceled', 'refused', 'storniert', 'stoniert'];
  v_aktiv boolean;
  v_ende timestamptz;
  v_zeit time;
  v_echt boolean;
  v_fahrer uuid[];
  f uuid;
  v_hat boolean;
  l record;
  d record;
begin
  select * into j from public.jobs where id = p_job_id;
  v_aktiv := found and coalesce(j.danach_dienstende, false)
             and public.trisar_norm_status(j.status) <> all (v_weg);
  if v_aktiv then
    v_ende := public.trisar_fahrt_ende(j);
    v_echt := j.ankunft_echt is not null;
    select array_agg(distinct x) into v_fahrer from (
      select j.driver_id as x where j.driver_id is not null
      union
      select ca.driver_id from public.convoy_assignments ca
       where ca.job_id = j.id and ca.driver_id is not null
         and lower(coalesce(ca.response_status, '')) not in ('refused', 'declined', 'abgelehnt')
    ) q;
  end if;
  v_fahrer := coalesce(v_fahrer, '{}'::uuid[]);
  if v_ende is not null then
    v_zeit := date_trunc('minute', v_ende at time zone 'Europe/Berlin')::time;
  end if;

  -- 1) Nicht mehr gueltige Verknuepfungen zuruecknehmen (Feld aus, storniert, Fahrer weg).
  for l in select * from public.dienstende_fahrt where job_id = p_job_id loop
    if not v_aktiv or not (l.driver_id = any (v_fahrer)) then
      -- Nur zuruecksetzen, wenn das Ende noch das von der Fahrt gesetzte ist.
      update public.driver_service_requests
         set service_end_time = l.ende_vorher
       where id = l.dienst_id and service_end_time is not distinct from l.ende_gesetzt;
      delete from public.dienstende_fahrt where job_id = l.job_id and driver_id = l.driver_id;
    end if;
  end loop;

  if not v_aktiv or v_zeit is null then
    return;
  end if;

  -- 2) Je Fahrer das Ende setzen oder nachziehen.
  foreach f in array v_fahrer loop
    select * into l from public.dienstende_fahrt where job_id = p_job_id and driver_id = f;
    v_hat := found;
    if v_hat then
      select * into d from public.driver_service_requests where id = l.dienst_id;
      if not found or lower(coalesce(d.status, '')) = 'refused' then
        delete from public.dienstende_fahrt where job_id = p_job_id and driver_id = f;
        v_hat := false;
      elsif d.service_end_time is distinct from l.ende_gesetzt then
        -- Jemand hat das Dienstende selbst geaendert: seins gilt.
        continue;
      end if;
    end if;

    if not v_hat then
      select * into d from public.driver_service_requests s
       where s.driver_id = f and lower(coalesce(s.status, '')) <> 'refused'
         and s.service_date in (j.ride_date, j.ride_date - 1)
       order by s.service_date desc, s.created_at desc
       limit 1;
      if not found then
        continue;
      end if;
      insert into public.dienstende_fahrt (job_id, driver_id, dienst_id, ende_vorher, ende_gesetzt)
      values (p_job_id, f, d.id, d.service_end_time, v_zeit);
    else
      update public.dienstende_fahrt set ende_gesetzt = v_zeit, aktualisiert = now()
       where job_id = p_job_id and driver_id = f;
    end if;

    if d.service_end_time is distinct from v_zeit then
      if v_echt then
        perform set_config('trisar.dienst_antwort', '1', true);  -- kein Push beim Nachziehen auf echt
      end if;
      update public.driver_service_requests set service_end_time = v_zeit where id = d.id;
      perform set_config('trisar.dienst_antwort', '', true);
      update public.profiles set service_end_time = v_zeit, service_end_date = d.service_date
       where id = f and service_end_date is not distinct from d.service_date;
    end if;
    update public.dienstende_fahrt set ende_gesetzt = v_zeit where job_id = p_job_id and driver_id = f;
  end loop;
end;

declare
  v integer := public.trisar_dienststart_vorlauf();
  a record;
  erste timestamptz;
  s timestamptz;
  tag date;
begin
  if p_fahrer is null or p_t_alt is null then
    return 'aus';
  end if;
  tag := (p_t_alt at time zone 'Europe/Berlin')::date;
  select * into a from public.trisar_dienst_spannen(p_fahrer, tag - 1, tag) x
   where x.requested_by = 'automatisch' and x.status = 'pending' and not x.geaendert
     and x.von <= p_t_alt and p_t_alt <= x.bis
   order by x.von desc limit 1;
  if not found then
    return 'nichts';
  end if;
  select min((j.ride_date + j.etd) at time zone 'Europe/Berlin') into erste
    from public.jobs j
   where j.driver_id = p_fahrer and j.etd is not null and public.trisar_fahrt_aktiv(j.status)
     and j.ride_date between a.tag and a.tag + 1
     and ((j.ride_date + j.etd) at time zone 'Europe/Berlin') between a.von and a.bis;
  if erste is null then
    delete from public.driver_service_requests where id = a.id;
    return 'zurueckgezogen';
  end if;
  if v is null then
    return 'bleibt';
  end if;
  s := erste - make_interval(mins => v);
  if s <= a.von then
    return 'bleibt';
  end if;
  if (s at time zone 'Europe/Berlin')::date = a.tag then
    update public.driver_service_requests set service_start_time = (s at time zone 'Europe/Berlin')::time where id = a.id;
    return 'verschoben';
  end if;
  -- Erste verbleibende Fahrt liegt so spaet, dass ihr Dienst an einem anderen Tag beginnt.
  delete from public.driver_service_requests where id = a.id;
  perform public.trisar_dienststart_sichern(p_fahrer, erste);
  return 'neu_berechnet';
end;

declare
  k uuid;
begin
  for k in select public.push_dispo_konten() loop
    if exists (select 1 from public.push_einstellungen e where e.user_id = k and 'dispo_dienst_pruefen' = any(e.aus)) then
      continue;
    end if;
    insert into public.push_ausgang (user_id, app, art, titel, text, daten)
    values (k, 'dispo', 'dispo_dienst_pruefen', 'Dienst prüfen',
      public.push_name(p_fahrer) || ': Fahrt ' || to_char(p_t at time zone 'Europe/Berlin', 'DD.MM. HH24:MI')
        || ' liegt nach dem Dienstende ' || to_char(p_ende, 'HH24:MI') || '. Bitte Dienst anpassen.',
      jsonb_build_object('ziel', 'fahrer', 'user_id', p_fahrer));
  end loop;
end;

declare
  v integer := public.trisar_dienststart_vorlauf();
  s timestamptz;
  tag_s date;
  zeit_s time;
  d record;
  p record;
  n record;
begin
  if v is null or p_fahrer is null or p_t is null or p_t <= p_jetzt then
    return 'aus';
  end if;
  s := p_t - make_interval(mins => v);
  tag_s := (s at time zone 'Europe/Berlin')::date;
  zeit_s := (s at time zone 'Europe/Berlin')::time;

  -- 2. Ein Dienst deckt die Fahrt.
  select * into d from public.trisar_dienst_spannen(p_fahrer, tag_s - 1, tag_s + 1) x
   where x.status <> 'refused' and x.von <= p_t and p_t <= x.bis
   order by x.von desc limit 1;
  if found then
    if d.requested_by = 'automatisch' and d.tag = tag_s and d.von > s then
      insert into public.driver_service_requests (driver_id, service_date, service_start_time, status, requested_by)
      values (p_fahrer, tag_s, zeit_s, 'pending', 'automatisch');
      return 'vorgezogen';
    end if;
    return 'gedeckt';
  end if;

  -- 3. Letzter Dienst vor der Fahrt.
  select * into p from public.trisar_dienst_spannen(p_fahrer, tag_s - 2, tag_s + 1) x
   where x.status <> 'refused' and x.von <= p_t
   order by x.von desc limit 1;
  if found and (p.tag = tag_s or p_t - p.bis < interval '3 hours') then
    if p.hat_ende then
      perform public.trisar_dienststart_hinweis(p_fahrer, p_t, p.ende_zeit);
      return 'nach_dienstende';
    end if;
    return 'gedeckt';
  end if;

  -- 5. Abgelehnt am Tag von S.
  if exists (select 1 from public.trisar_dienst_spannen(p_fahrer, tag_s, tag_s) x where x.status = 'refused') then
    return 'abgelehnt';
  end if;

  -- 4. Dienst am Tag von S beginnt erst nach der Fahrt: vorziehen. Ende, Pausen und Treffpunkt bleiben
  -- (trisar_dienst_ein_pro_tag_vorher / trisar_dienst_zusammenfuehren), der Fahrer bestaetigt die Aenderung.
  select * into n from public.trisar_dienst_spannen(p_fahrer, tag_s, tag_s) x
   where x.status <> 'refused' and x.von > p_t
   order by x.von limit 1;
  if found then
    insert into public.driver_service_requests (driver_id, service_date, service_start_time, status, requested_by)
    -- Herkunft bleibt: ein Dispo-Dienst wird dadurch nie zum automatischen (nie automatisch zurueckgezogen).
    values (p_fahrer, tag_s, zeit_s, 'pending', coalesce(n.requested_by, 'dispo'));
    return 'vorgezogen';
  end if;

  -- 6. Neuer Dienst.
  insert into public.driver_service_requests (driver_id, service_date, service_start_time, status, requested_by)
  values (p_fahrer, tag_s, zeit_s, 'pending', 'automatisch');
  return 'neu';
end;

select case when jsonb_typeof(e.wert) = 'number' and (e.wert #>> '{}')::numeric > 0
            then (e.wert #>> '{}')::numeric::integer end
  from public.dispo_einstellungen e where e.schluessel = 'dienststart_vorlauf_min';

declare
  v_job_id uuid;
begin
  if tg_op = 'DELETE' then
    return old;
  end if;

  if new.active_job_id is not null then
    perform public.trisar_evaluate_job_status(new.active_job_id, 'driver_live_trigger');
  end if;

  for v_job_id in
    select j.id
    from public.jobs j
    where j.driver_id = new.driver_id
      -- Schon oben bewertet. Zweimal je Punkt hob den Abfahrts-Treffer wieder auf
      -- (zweiter Lauf sieht keine Bewegung, zieht einen ab), "unterwegs" kam so nie.
      and j.id is distinct from new.active_job_id
      and lower(coalesce(j.status, '')) in (
        'pending', 'assigned', 'offen', 'new', 'requested', 'offered', 'zugewiesen',
        'at_pickup', 'pickup', 'beim_pickup', 'beim pickup',
        'in_progress', 'unterwegs', 'started', 'on_trip', 'ongoing', 'active'
      )
    order by j.ride_date nulls last, j.etd nulls last
    limit 5
  loop
    perform public.trisar_evaluate_job_status(v_job_id, 'driver_live_trigger');
  end loop;

  return new;
end;

declare
  v_fahrt constant text[] := array['in_progress', 'unterwegs', 'started', 'on_trip', 'ongoing', 'active'];
  v_fertig constant text[] := array['done', 'completed', 'arrived', 'beendet'];
  v_weg constant text[] := array['cancelled', 'canceled', 'refused', 'storniert', 'stoniert'];
  st_neu text := public.trisar_norm_status(new.status);
  st_alt text := case when tg_op = 'UPDATE' then public.trisar_norm_status(old.status) end;
  -- Die Engine (GPS) setzt den Status ueber trisar_transition_job_status, das markiert die Fahrt.
  v_automatisch boolean := coalesce(current_setting('trisar.status_protokolliert', true), '') = new.id::text;
begin
  if st_neu = any (v_fahrt) and (st_alt is null or st_alt <> all (v_fahrt)) then
    if st_alt = any (v_fertig) and new.abfahrt_echt is not null then
      null;  -- Dispo setzt eine beendete Fahrt zurueck auf unterwegs: Abfahrt bleibt
    else
      new.abfahrt_echt := now();
      new.abfahrt_quelle := case when v_automatisch then 'gps' else 'status' end;
    end if;
    new.ankunft_echt := null;
  elsif st_neu = any (v_fertig) and (st_alt is null or st_alt <> all (v_fertig)) then
    new.ankunft_echt := now();
  elsif st_neu <> all (v_fahrt) and st_neu <> all (v_fertig) and st_neu <> all (v_weg) then
    -- Zurueck auf offen oder beim Gast: noch nicht losgefahren
    new.abfahrt_echt := null;
    new.abfahrt_quelle := null;
    new.ankunft_echt := null;
  end if;

  if st_neu = any (v_fertig) then
    new.ankunft_erwartet := new.ankunft_echt;
  elsif st_neu = any (v_fahrt) then
    new.ankunft_erwartet := public.trisar_ankunft_erwartet(new);
  elsif st_neu <> all (v_weg) then
    new.ankunft_erwartet := null;
  end if;
  return new;
end;

declare
  rest numeric;
  v numeric := coalesce(t.verbrauch_l_100km, p_verbrauch);
begin
  pct := case
    when t.fuel_level_pct between 0 and 100 then t.fuel_level_pct
    when t.oem_fuel_l >= 0 and p_tank > 0 then least(100, greatest(0, round(t.oem_fuel_l / p_tank * 100)))::integer
  end;
  if pct is null then
    return;
  end if;
  rest := coalesce(t.oem_remaining_distance_km, t.geschaetzte_reichweite_km);
  voll := case
    when rest > 0 and pct >= 5 then round(rest * 100 / pct)::integer
    when v > 0 and p_tank > 0 then round(p_tank / v * 100)::integer
    when p_kwh > 0 and p_akku > 0 then round(p_akku / p_kwh * 100)::integer
  end;
end

declare
  v_job public.jobs%rowtype;
  v_runtime public.job_status_runtime%rowtype;
  v_status text;
  v_open_statuses constant text[] := array['pending', 'assigned', 'offen', 'new', 'requested', 'offered', 'zugewiesen'];
  v_pickup_statuses constant text[] := array['at_pickup', 'pickup', 'beim_pickup', 'beim pickup'];
  v_trip_statuses constant text[] := array['in_progress', 'unterwegs', 'started', 'on_trip', 'ongoing', 'active'];
  v_done_statuses constant text[] := array['done', 'completed', 'arrived', 'beendet'];
  v_terminal_statuses constant text[] := array['cancelled', 'canceled', 'refused', 'storniert', 'stoniert'];
  v_enter_radius integer := public.trisar_get_setting_int('status_pickup_enter_radius_m', 50);
  v_exit_radius integer := public.trisar_get_setting_int('status_pickup_exit_radius_m', 100);
  v_depart_hits_required integer := public.trisar_get_setting_int('status_pickup_depart_hits', 3);
  v_progress_delta integer := public.trisar_get_setting_int('status_progress_delta_m', 25);
  v_done_radius integer := public.trisar_get_setting_int('status_dropoff_done_radius_m', 50);
  v_done_hits_required integer := public.trisar_get_setting_int('status_dropoff_done_hits', 2);
  v_pickup_distance integer;
  v_dropoff_distance integer;
  v_pickup_exit_hits integer;
  v_dropoff_near_hits integer;
  v_depart_confirmed boolean := false;
  v_dropoff_progressing boolean := false;
  v_live public.driver_live_locations%rowtype;
  v_pickup_lat double precision;
  v_pickup_lng double precision;
  v_dropoff_lat double precision;
  v_dropoff_lng double precision;
  v_pickup_luft integer;
  v_dropoff_luft integer;
  v_pickup_ort public.orte%rowtype;
  v_dropoff_ort public.orte%rowtype;
  v_std public.orte_standard%rowtype;
  v_pickup_rein integer;
  v_pickup_raus integer;
  v_dropoff_rein integer;
begin
  select * into v_job
  from public.jobs
  where id = p_job_id;

  if not found then
    return null;
  end if;

  v_status := public.trisar_norm_status(v_job.status);

  insert into public.job_status_runtime(job_id)
  values (p_job_id)
  on conflict (job_id) do nothing;

  select * into v_runtime
  from public.job_status_runtime
  where job_id = p_job_id
  for update;

  -- Luftlinie von der frischen Live-Position (App alle 5 s, OBD je Paket) zu Abhol- und Zielort.
  -- Die Routen-Distanz (ext_driver_to_*) rechnet nur ein Sync (Annehmen, Gateway, Web-Details),
  -- bei iOS/Android lief der waehrend der Anfahrt gar nicht, deshalb kam nie "beim Gast".
  -- Koordinaten: TomTom-Payload der Fahrt (von = Abholort, nach = Ziel), sonst der Anfahrts-Payloads.
  v_pickup_lat := coalesce((v_job.ext_route_payload->'von'->>'lat')::double precision,
                           (v_job.ext_driver_to_pickup_payload->'nach'->>'lat')::double precision);
  v_pickup_lng := coalesce((v_job.ext_route_payload->'von'->>'lon')::double precision,
                           (v_job.ext_route_payload->'von'->>'lng')::double precision,
                           (v_job.ext_driver_to_pickup_payload->'nach'->>'lon')::double precision);
  v_dropoff_lat := coalesce((v_job.ext_route_payload->'nach'->>'lat')::double precision,
                            (v_job.ext_driver_to_dropoff_payload->'nach'->>'lat')::double precision);
  v_dropoff_lng := coalesce((v_job.ext_route_payload->'nach'->>'lon')::double precision,
                            (v_job.ext_route_payload->'nach'->>'lng')::double precision,
                            (v_job.ext_driver_to_dropoff_payload->'nach'->>'lon')::double precision);

  -- Eigene Orte der Dispo: Radien (und genauer Pin) des Orts statt Standard.
  -- Erst die Zuordnung aus der Fahrt (gewaehlt beim Erstellen), sonst der naechste Ort, in dessen
  -- Rausfahr-Radius die Adresse der Fahrt liegt (getippte Adresse, Import, alte Fahrten).
  select * into v_std from public.orte_standard limit 1;
  if v_job.pickup_ort_id is not null then
    select * into v_pickup_ort from public.orte where id = v_job.pickup_ort_id;
  elsif v_pickup_lat is not null then
    select o.* into v_pickup_ort from public.orte o
     where public.trisar_luftlinie_m(v_pickup_lat, v_pickup_lng, o.lat, o.lng) <= o.radius_raus_m
     order by public.trisar_luftlinie_m(v_pickup_lat, v_pickup_lng, o.lat, o.lng) limit 1;
  end if;
  if v_job.dropoff_ort_id is not null then
    select * into v_dropoff_ort from public.orte where id = v_job.dropoff_ort_id;
  elsif v_dropoff_lat is not null then
    select o.* into v_dropoff_ort from public.orte o
     where public.trisar_luftlinie_m(v_dropoff_lat, v_dropoff_lng, o.lat, o.lng) <= o.radius_raus_m
     order by public.trisar_luftlinie_m(v_dropoff_lat, v_dropoff_lng, o.lat, o.lng) limit 1;
  end if;
  if v_pickup_ort.id is not null then
    v_pickup_lat := v_pickup_ort.lat;
    v_pickup_lng := v_pickup_ort.lng;
  end if;
  if v_dropoff_ort.id is not null then
    v_dropoff_lat := v_dropoff_ort.lat;
    v_dropoff_lng := v_dropoff_ort.lng;
  end if;
  v_pickup_rein := coalesce(v_pickup_ort.radius_rein_m, v_std.radius_rein_m, v_enter_radius);
  v_pickup_raus := greatest(coalesce(v_pickup_ort.radius_raus_m, v_std.radius_raus_m, v_exit_radius), v_pickup_rein + 1);
  v_dropoff_rein := coalesce(v_dropoff_ort.radius_rein_m, v_std.radius_rein_m, v_done_radius);

  if v_job.driver_id is not null then
    select * into v_live
    from public.driver_live_locations
    where driver_id = v_job.driver_id
      and coalesce(captured_at, updated_at) > now() - interval '2 minutes';
    if found and v_live.lat is not null and v_live.lng is not null then
      v_pickup_luft := public.trisar_luftlinie_m(v_live.lat, v_live.lng, v_pickup_lat, v_pickup_lng);
      v_dropoff_luft := public.trisar_luftlinie_m(v_live.lat, v_live.lng, v_dropoff_lat, v_dropoff_lng);
    end if;
  end if;

  -- Routen-Distanz nur, wenn sie frisch ist. Sie bleibt nach dem letzten Sync in der Fahrt stehen
  -- (z. B. 15 m zum Ziel nach dem Beenden). Setzte die Dispo die Fahrt danach wieder auf unterwegs
  -- oder offen, sprang sie mit diesem alten Wert sofort zurueck auf beendet bzw. beim Gast.
  v_pickup_distance := coalesce(
    v_pickup_luft,
    case when v_job.ext_driver_to_pickup_last_sync_at > now() - interval '5 minutes'
         then v_job.ext_driver_to_pickup_distance_m end,
    2147483647);
  v_dropoff_distance := coalesce(
    v_dropoff_luft,
    case when v_job.ext_driver_to_dropoff_last_sync_at > now() - interval '5 minutes'
         then v_job.ext_driver_to_dropoff_distance_m end,
    2147483647);
  v_pickup_exit_hits := coalesce(v_runtime.pickup_exit_hits, 0);
  v_dropoff_near_hits := coalesce(v_runtime.dropoff_near_hits, 0);

  if v_status = any(v_terminal_statuses) or v_status = any(v_done_statuses) then
    update public.job_status_runtime
    set pickup_exit_hits = 0,
        dropoff_near_hits = 0,
        last_pickup_distance_m = null,
        last_dropoff_distance_m = null,
        updated_at = now()
    where job_id = p_job_id;
    return v_job.status;
  end if;

  if v_status = any(v_open_statuses) then
    -- Fahrt ohne Start: der Start IST der Standort des Fahrers, er steht also sofort "am Abholort".
    -- Erst nach dem Annehmen (assigned/zugewiesen) darf daraus "Beim Gast" werden, sonst
    -- verschwindet das Annehmen in der Fahrer-App, bevor er es tippen kann.
    if v_pickup_distance <= v_pickup_rein and public.trisar_fahrt_ist_dran(v_job)
       and not (coalesce(v_job.start_fahrerstandort, false) and v_status not in ('assigned', 'zugewiesen')) then
      perform public.trisar_transition_job_status(
        p_job_id,
        'at_pickup',
        p_source,
        jsonb_build_object('pickup_distance_m', v_pickup_distance, 'radius_m', v_pickup_rein, 'ort', v_pickup_ort.name)
      );
      v_status := 'at_pickup';
      v_pickup_exit_hits := 0;
      v_dropoff_near_hits := 0;
    end if;
  elsif v_status = any(v_pickup_statuses) then
    if v_pickup_distance = 2147483647 then
      -- Ohne Distanz (weder Luftlinie noch Route) keine Entscheidung. Vorher zaehlte NULL als unendlich weit weg,
      -- und der Auftrag sprang faelschlich auf unterwegs, bevor der Fahrer losgefahren war.
      null;
    elsif v_pickup_distance > v_pickup_raus then
      -- Beim Gast ab dem Reinfahr-Radius, unterwegs erst ausserhalb des (groesseren) Rausfahr-Radius,
      -- sobald genug Punkte in Folge draussen sind (status_pickup_depart_hits, gegen GPS-Ausreisser).
      v_pickup_exit_hits := v_pickup_exit_hits + 1;
    else
      v_pickup_exit_hits := 0;
    end if;

    if v_pickup_exit_hits >= greatest(v_depart_hits_required, 1) then
      perform public.trisar_transition_job_status(
        p_job_id,
        'in_progress',
        p_source,
        jsonb_build_object(
          'pickup_distance_m', v_pickup_distance,
          'dropoff_distance_m', case when v_dropoff_distance = 2147483647 then null else v_dropoff_distance end,
          'departure_hits', v_pickup_exit_hits
        )
      );
      v_status := 'in_progress';
      v_pickup_exit_hits := 0;
      v_dropoff_near_hits := 0;
    end if;
  elsif v_status = any(v_trip_statuses) then
    if v_dropoff_distance <= v_dropoff_rein then
      v_dropoff_near_hits := v_dropoff_near_hits + 1;
    else
      v_dropoff_near_hits := greatest(v_dropoff_near_hits - 1, 0);
    end if;

    if v_dropoff_near_hits >= greatest(v_done_hits_required, 1) then
      perform public.trisar_transition_job_status(
        p_job_id,
        'done',
        p_source,
        jsonb_build_object('dropoff_distance_m', v_dropoff_distance, 'dropoff_hits', v_dropoff_near_hits,
                           'radius_m', v_dropoff_rein, 'ort', v_dropoff_ort.name)
      );
      v_status := 'done';
      v_pickup_exit_hits := 0;
      v_dropoff_near_hits := 0;
    end if;
  end if;

  update public.job_status_runtime
  set pickup_exit_hits = v_pickup_exit_hits,
      dropoff_near_hits = v_dropoff_near_hits,
      last_pickup_distance_m = case when v_pickup_distance = 2147483647 then null else v_pickup_distance end,
      last_dropoff_distance_m = case when v_dropoff_distance = 2147483647 then null else v_dropoff_distance end,
      updated_at = now()
  where job_id = p_job_id;

  return v_status;
end;

declare
  v_lat double precision;
  v_lng double precision;
begin
  if p_job.driver_id is null then
    return null;
  end if;
  if public.trisar_norm_status(p_job.status) not in (
       'pending', 'assigned', 'offen', 'new', 'requested', 'offered', 'zugewiesen') then
    return null;
  end if;
  if not public.trisar_fahrt_ist_dran(p_job) then
    return null;
  end if;
  select l.lat, l.lng into v_lat, v_lng
    from public.driver_live_locations l
   where l.driver_id = p_job.driver_id
     and coalesce(l.captured_at, l.updated_at) > now() - interval '15 minutes'
   order by coalesce(l.captured_at, l.updated_at) desc
   limit 1;
  if v_lat is null or v_lng is null then
    return null;
  end if;
  return to_char(v_lat, 'FM990.000000') || ', ' || to_char(v_lng, 'FM9990.000000');
end;

declare
  v_plan timestamptz;
begin
  if exists (
    select 1 from public.jobs o
    where o.driver_id = p_job.driver_id
      and o.id <> p_job.id
      and public.trisar_norm_status(o.status) in (
        'at_pickup', 'pickup', 'beim_pickup', 'beim pickup',
        'in_progress', 'unterwegs', 'started', 'on_trip', 'ongoing', 'active')
  ) then
    return false;
  end if;
  if p_job.ride_date is null or p_job.etd is null then
    return true;
  end if;
  v_plan := (p_job.ride_date + p_job.etd) at time zone 'Europe/Berlin';
  return v_plan <= now() + make_interval(mins => public.trisar_get_setting_int('status_vorlauf_min', 90))
     and v_plan >= now() - interval '3 hours';
end;

declare
  j public.jobs%rowtype;
  p record;
  v_schluessel text;
  v_drin timestamptz;
begin
  if new.lat is null or new.lng is null then return null; end if;
  for j in
    select * from public.jobs x
     where x.driver_id = new.driver_id
       and public.trisar_norm_status(x.status) in ('in_progress', 'unterwegs', 'started', 'on_trip', 'ongoing', 'active')
     order by x.ride_date desc nulls last, x.etd desc nulls last
     limit 3
  loop
    -- 1) GPS-Abfahrt
    if j.abfahrt_quelle is distinct from 'gps' then
      select * into p from public.trisar_abholpunkt(j);
      if p.lat is not null
         and public.trisar_luftlinie_m(new.lat, new.lng, p.lat, p.lng) > p.raus_m then
        -- Abfahrt = letzter Punkt noch im Reinfahr-Radius (da stand er beim Gast), sonst dieser Punkt.
        -- Am liebsten der letzte Stillstand (unter 2 m/s), da rollte er los.
        select coalesce(max(l.captured_at) filter (where coalesce(l.speed_mps, 0) < 2), max(l.captured_at))
          into v_drin from public.driver_location_history l
         where l.driver_id = new.driver_id
           and l.captured_at >= coalesce(j.abfahrt_echt, now() - interval '6 hours')
           and l.captured_at <= coalesce(new.captured_at, now())
           and public.trisar_luftlinie_m(l.lat, l.lng, p.lat, p.lng) <= p.rein_m;
        update public.jobs
           set abfahrt_echt = coalesce(v_drin, new.captured_at, now()),
               abfahrt_quelle = 'gps'
         where id = j.id;
      end if;
    end if;

    -- 2) Live-Ankunft holen (gedrosselt)
    if j.ext_driver_to_dropoff_last_sync_at is null or j.ext_driver_to_dropoff_last_sync_at < now() - interval '2 minutes' then
      insert into public.ziel_eta_takt (job_id, zuletzt) values (j.id, now())
        on conflict (job_id) do update set zuletzt = now()
        where ziel_eta_takt.zuletzt < now() - interval '2 minutes';
      if found then
        select value #>> '{}' into v_schluessel from public.integration_settings where key = 'edge_service_role_key';
        if coalesce(v_schluessel, '') <> '' then
          perform net.http_post(
            url := 'http://kong:8000/functions/v1/external-sync',
            body := jsonb_build_object('reason', 'live_view', 'job_ids', jsonb_build_array(j.id),
                                       'requested_by', j.driver_id, 'nur_ziel', true,
                                       'current_location', jsonb_build_object('lat', new.lat, 'lng', new.lng)),
            headers := jsonb_build_object('Content-Type', 'application/json',
                                          'Authorization', 'Bearer ' || v_schluessel,
                                          'apikey', v_schluessel),
            timeout_milliseconds := 30000
          );
        end if;
      end if;
    end if;
  end loop;
  return null;
exception when others then
  -- Der Standort des Fahrers darf nie daran scheitern.
  return null;
end;

declare
  v_vin text := upper(trim(coalesce(p_vin, '')));
  t public.obd_tracker%rowtype;
  g public.vin_typen%rowtype;
  r public.vin_regeln%rowtype;
  v_id uuid;
  v_fahrer uuid;
  v_aktion text;
  v_name text;
  d uuid;
begin
  if v_vin !~ '^[A-HJ-NPR-Z0-9]{17}$' then
    return jsonb_build_object('aktion', 'ungueltig');
  end if;
  select * into t from public.obd_tracker where imei = p_imei;
  if t.imei is null then
    return jsonb_build_object('aktion', 'tracker_unbekannt');
  end if;

  select id into v_id from public.vehicles where upper(vin) = v_vin;
  if v_id is not null then
    v_aktion := 'bekannt';
  elsif t.vehicle_id is not null
        and exists (select 1 from public.vehicles v where v.id = t.vehicle_id and coalesce(trim(v.vin), '') = '') then
    update public.vehicles set vin = v_vin where id = t.vehicle_id;
    v_id := t.vehicle_id;
    v_aktion := 'vin_eingetragen';
  else
    select * into g from public.vin_typen where typ = left(v_vin, 8);
    if g.typ is null then
      select * into r from public.vin_regeln where v_vin ~ muster order by reihenfolge limit 1;
    end if;
    v_name := coalesce(g.brand_model, r.brand_model,
      nullif(trim(coalesce(nullif(trim(p_marke), ''), 'Unbekannt') || ' ' || coalesce(trim(p_modell), '')), ''));
    -- hsn/tsn loesen trg_fahrzeug_kba_fuellen aus, der fuellt was noch fehlt.
    insert into public.vehicles (brand_model, trim, fuel_type, seat_count, vin, hsn, tsn, neu_erkannt)
    values (v_name, coalesce(g.trim, r.trim), coalesce(g.fuel_type, r.fuel_type), coalesce(g.seat_count, r.seat_count),
            v_vin, g.hsn, g.tsn, true)
    returning id into v_id;
    v_aktion := 'angelegt';
  end if;

  -- Ein Auto hat einen Tracker.
  if t.vehicle_id is distinct from v_id then
    update public.obd_tracker set vehicle_id = null where vehicle_id = v_id and imei <> t.imei;
    update public.obd_tracker set vehicle_id = v_id where imei = t.imei;
  end if;

  select driver_id into v_fahrer from public.imei_driver_map where imei = t.imei and is_active limit 1;
  if v_fahrer is not null then
    update public.profiles set vehicle_id = v_id where id = v_fahrer and vehicle_id is distinct from v_id;
  end if;

  if v_aktion = 'angelegt' then
    for d in select public.push_dispo_konten() loop
      perform public.push_melden(d, 'dispo', 'dispo_fahrzeug_neu', 'Neues Fahrzeug erkannt',
        v_name || ' in Tracker ' || t.nummer || coalesce(' · ' || public.push_name(v_fahrer), ''),
        jsonb_build_object('ziel', 'fahrzeug', 'vehicle_id', v_id));
    end loop;
  end if;

  return jsonb_build_object('aktion', v_aktion, 'vehicle_id', v_id, 'fahrer', v_fahrer,
    'gelernt', g.typ is not null, 'regel', r.muster);
end;

declare
  vid uuid;
  d record;
  w record;
begin
  vid := public.trisar_fahrzeug_zum_tracker(new.imei, new.vin);
  if vid is null then
    return null;
  end if;
  select * into d from public.trisar_fahrzeug_variante(vid);
  select * into w from public.trisar_energie_werte(new, d.tank, d.verbrauch, d.akku, d.kwh);
  if w.pct is null then
    return null;
  end if;
  update public.vehicles
     set battery_fuel_percent = w.pct,
         range_km = w.voll
   where id = vid
     and (battery_fuel_percent is distinct from w.pct or range_km is distinct from w.voll);
  return null;
end

declare
  k public.kba_typen%rowtype;
begin
  new.hsn := nullif(upper(trim(coalesce(new.hsn, ''))), '');
  new.tsn := nullif(upper(trim(coalesce(new.tsn, ''))), '');
  if new.hsn is null or new.tsn is null then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.hsn is not distinct from old.hsn and new.tsn is not distinct from old.tsn then
    return new;
  end if;
  select * into k from public.kba_typen where hsn = new.hsn and tsn = new.tsn;
  if k.hsn is null then
    return new;
  end if;
  if position(' ' in trim(coalesce(new.brand_model, ''))) = 0 and k.brand_model is not null then
    new.brand_model := k.brand_model;
  end if;
  new.trim := coalesce(nullif(trim(new.trim), ''), k.trim);
  new.fuel_type := coalesce(nullif(trim(new.fuel_type), ''), k.fuel_type);
  new.seat_count := coalesce(new.seat_count, case when k.sitze > 1 then k.sitze - 1 end);
  return new;
end;

begin
  if new.neu_erkannt and coalesce(trim(new.license_plate), '') <> '' then
    new.neu_erkannt := false;
  end if;
  return new;
end;

declare
  t public.vehicle_telemetry_live;
  w record;
  tank numeric;
  verbrauch numeric;
  akku numeric;
  kwh numeric;
begin
  select coalesce(new.tank_l, f.tank_l), f.verbrauch_l_100km, f.akku_kwh, f.verbrauch_kwh_100km
    into tank, verbrauch, akku, kwh
    from (select 1) x left join public.fahrzeug_varianten f on f.id = new.variante_id;
  if new.variante_id is not null and coalesce(trim(new.fuel_type), '') = '' then
    new.fuel_type := (select kraftstoff from public.fahrzeug_varianten where id = new.variante_id);
  end if;
  select l.* into t
    from public.vehicle_telemetry_live l
   where public.trisar_fahrzeug_zum_tracker(l.imei, l.vin) = new.id
   order by l.captured_at desc nulls last
   limit 1;
  if t.imei is not null then
    select * into w from public.trisar_energie_werte(t, tank, verbrauch, akku, kwh);
    if w.pct is not null then
      new.battery_fuel_percent := w.pct;
      new.range_km := w.voll;
      return new;
    end if;
  end if;
  new.range_km := case
    when verbrauch > 0 and tank > 0 then round(tank / verbrauch * 100)::integer
    when kwh > 0 and akku > 0 then round(akku / kwh * 100)::integer
    else new.range_km
  end;
  return new;
end

declare
  v_ort text;
begin
  if new.flight_origin is not null and new.flight_origin ~ '^[A-Z]{3}$' then
    select ort into v_ort from public.flughafen_orte where iata = new.flight_origin;
    if v_ort is not null then
      new.flight_origin := v_ort || ' (' || new.flight_origin || ')';
    end if;
  end if;
  return new;
end;

declare
  v_raw text;
begin
  begin
    select value #>> '{}' into v_raw
    from public.integration_settings
    where key = p_key;
  exception
    when undefined_table then
      return p_fallback;
  end;

  if v_raw is null or btrim(v_raw) = '' then
    return p_fallback;
  end if;

  begin
    return v_raw::integer;
  exception
    when others then
      return p_fallback;
  end;
end;

declare
  v_abholung_neu boolean;
  v_ziel_neu boolean;
  v_status_neu text;
begin
  v_abholung_neu := new.pickup_address is distinct from old.pickup_address
    and not coalesce(new.start_fahrerstandort, false);
  v_ziel_neu := new.dropoff_address is distinct from old.dropoff_address;
  if not v_abholung_neu and not v_ziel_neu then
    return new;
  end if;

  -- Alte Linie weg: Apps, die in den Sekunden bis zur neuen Route laden, rechnen sonst mit ihren Enden
  -- (CarPlay gab so die alte Abholung an Apple Karten). Ohne Linie rechnen sie selbst aus den Adressen.
  new.ext_route_polyline := null;

  if v_abholung_neu then
    if new.ext_route_payload is not null then
      new.ext_route_payload := new.ext_route_payload - 'von';
    end if;
    new.ext_driver_to_pickup_payload := null;
    new.ext_driver_to_pickup_distance_m := null;
    new.ext_driver_to_pickup_last_sync_at := null;

    -- Nur wenn die Dispo den Status nicht selbst im selben Speichern geaendert hat.
    if new.status is not distinct from old.status
       and public.trisar_norm_status(new.status) in ('at_pickup', 'pickup', 'beim_pickup', 'beim pickup') then
      v_status_neu := case when new.driver_id is not null then 'assigned' else 'pending' end;
      insert into public.job_status_history(job_id, from_status, to_status, source, meta)
      values (new.id, old.status, v_status_neu, 'adresse_neu',
              jsonb_build_object('driver_id', new.driver_id,
                                 'abholung_alt', old.pickup_address,
                                 'abholung_neu', new.pickup_address));
      -- jobs_status_protokoll soll denselben Wechsel nicht noch einmal als 'app' schreiben.
      perform set_config('trisar.status_protokolliert', new.id::text, true);
      new.status := v_status_neu;
    end if;
  end if;

  if v_ziel_neu then
    if new.ext_route_payload is not null then
      new.ext_route_payload := new.ext_route_payload - 'nach';
    end if;
    new.ext_driver_to_dropoff_payload := null;
    new.ext_driver_to_dropoff_distance_m := null;
    new.ext_driver_to_dropoff_last_sync_at := null;
  end if;

  -- Zaehler der Statusregel gehoeren zur alten Adresse.
  update public.job_status_runtime
  set pickup_exit_hits = case when v_abholung_neu then 0 else pickup_exit_hits end,
      dropoff_near_hits = case when v_ziel_neu then 0 else dropoff_near_hits end,
      last_pickup_distance_m = case when v_abholung_neu then null else last_pickup_distance_m end,
      last_dropoff_distance_m = case when v_ziel_neu then null else last_dropoff_distance_m end,
      updated_at = now()
  where job_id = new.id;

  return new;
end;

begin
  if tg_op = 'INSERT' and not coalesce(new.danach_dienstende, false) then
    return null;
  end if;
  if tg_op = 'UPDATE' and not coalesce(new.danach_dienstende, false) and not coalesce(old.danach_dienstende, false) then
    return null;
  end if;
  perform public.trisar_dienstende_fahrt_anwenden(new.id);
  return null;
exception when others then
  -- Eine Fahrt darf nie am Dienstende scheitern.
  raise warning 'danach_dienstende %: %', new.id, sqlerrm;
  return null;
end;

declare
  t_alt timestamptz;
  t_neu timestamptz;
  alt_aktiv boolean;
  neu_aktiv boolean;
begin
  if tg_op = 'UPDATE' then
    alt_aktiv := old.driver_id is not null and old.etd is not null and public.trisar_fahrt_aktiv(old.status);
    t_alt := (old.ride_date + old.etd) at time zone 'Europe/Berlin';
  else
    alt_aktiv := false;
  end if;
  neu_aktiv := new.driver_id is not null and new.etd is not null and public.trisar_fahrt_aktiv(new.status);
  t_neu := (new.ride_date + new.etd) at time zone 'Europe/Berlin';

  if tg_op = 'UPDATE' and alt_aktiv = neu_aktiv and old.driver_id is not distinct from new.driver_id
     and t_alt is not distinct from t_neu then
    return null;
  end if;

  -- Fehler hier duerfen das Speichern der Fahrt nie verhindern.
  begin
    if alt_aktiv then
      perform public.trisar_dienststart_aufraeumen(old.driver_id, t_alt);
    end if;
    if neu_aktiv then
      perform public.trisar_dienststart_sichern(new.driver_id, t_neu);
    end if;
  exception when others then
    raise warning 'Dienststart automatisch: %', sqlerrm;
  end;
  return null;
end;

declare
  -- Route passt noch nicht zur neuen Adresse: Koordinaten nicht verwenden.
  v_start_veraltet boolean := tg_op = 'UPDATE'
    and new.pickup_address is distinct from old.pickup_address
    and new.ext_route_payload is not distinct from old.ext_route_payload;
  v_ziel_veraltet boolean := tg_op = 'UPDATE'
    and new.dropoff_address is distinct from old.dropoff_address
    and new.ext_route_payload is not distinct from old.ext_route_payload;
begin
  if new.pickup_ort_id is null then
    new.pickup_ort_id := public.trisar_ort_finden(
      new.pickup_address,
      case when v_start_veraltet then null else (new.ext_route_payload->'von'->>'lat')::double precision end,
      case when v_start_veraltet then null else coalesce((new.ext_route_payload->'von'->>'lon')::double precision, (new.ext_route_payload->'von'->>'lng')::double precision) end);
  end if;
  if new.dropoff_ort_id is null then
    new.dropoff_ort_id := public.trisar_ort_finden(
      new.dropoff_address,
      case when v_ziel_veraltet then null else (new.ext_route_payload->'nach'->>'lat')::double precision end,
      case when v_ziel_veraltet then null else coalesce((new.ext_route_payload->'nach'->>'lon')::double precision, (new.ext_route_payload->'nach'->>'lng')::double precision) end);
  end if;
  return new;
end;

declare
  v_text text;
begin
  -- Editoren zeigen bei solchen Fahrten "Standort Fahrer" im Startfeld und speichern das zurueck.
  if lower(btrim(coalesce(new.pickup_address, ''))) = 'standort fahrer' then
    new.pickup_address := case when tg_op = 'UPDATE' and old.start_fahrerstandort then old.pickup_address else '' end;
  end if;

  if coalesce(btrim(new.pickup_address), '') = '' then
    new.start_fahrerstandort := true;
  elsif tg_op = 'UPDATE'
        and old.start_fahrerstandort
        and new.pickup_address is distinct from old.pickup_address
        and not public.trisar_ist_koordinatentext(new.pickup_address) then
    -- Echte Adresse eingetragen: ab jetzt normale Fahrt.
    new.start_fahrerstandort := false;
  end if;

  if not new.start_fahrerstandort then
    return new;
  end if;

  if tg_op = 'UPDATE' and new.driver_id is distinct from old.driver_id then
    new.pickup_address := '';
  end if;

  new.pickup_name := 'Standort Fahrer';
  new.pickup_ort_id := null;

  if coalesce(btrim(new.pickup_address), '') = '' then
    new.pickup_address := '';
    v_text := public.trisar_fahrerstandort_text(new);
    if v_text is not null then
      new.pickup_address := v_text;
    end if;
  end if;
  return new;
end;

begin
  if tg_op = 'DELETE' then
    return old;
  end if;

  if pg_trigger_depth() > 1 then
    return new;
  end if;

  -- Status von aussen gesetzt (Dispo-Editor, Fahrer-App). Die Engine selbst schreibt ueber
  -- trisar_transition_job_status und landet oben bei pg_trigger_depth() > 1.
  -- Den gewaehlten Status nicht im selben Moment ueberstimmen, nur die Zaehler zuruecksetzen.
  if tg_op = 'UPDATE'
     and public.trisar_norm_status(new.status) is distinct from public.trisar_norm_status(old.status) then
    update public.job_status_runtime
    set pickup_exit_hits = 0,
        dropoff_near_hits = 0,
        last_pickup_distance_m = null,
        last_dropoff_distance_m = null,
        updated_at = now()
    where job_id = new.id;
    return new;
  end if;

  -- Speichern im Editor schreibt status immer mit, auch unveraendert. Das ist kein neuer Messpunkt
  -- und darf keinen Treffer zaehlen (zwei Mal Speichern machte aus unterwegs sonst beendet).
  -- Neu bewerten nur, wenn sich Fahrer oder Distanzen wirklich geaendert haben.
  if tg_op = 'UPDATE'
     and new.driver_id is not distinct from old.driver_id
     and new.ext_driver_to_pickup_distance_m is not distinct from old.ext_driver_to_pickup_distance_m
     and new.ext_driver_to_dropoff_distance_m is not distinct from old.ext_driver_to_dropoff_distance_m then
    return new;
  end if;

  perform public.trisar_evaluate_job_status(new.id, 'jobs_trigger');
  return new;
end;

declare
  v_job uuid := coalesce(new.job_id, old.job_id);
begin
  if exists (select 1 from public.jobs where id = v_job and danach_dienstende)
     or exists (select 1 from public.dienstende_fahrt where job_id = v_job) then
    perform public.trisar_dienstende_fahrt_anwenden(v_job);
  end if;
  return null;
exception when others then
  raise warning 'danach_dienstende konvoi %: %', v_job, sqlerrm;
  return null;
end;

declare
  v_job public.jobs%rowtype;
  v_text text;
begin
  for v_job in
    select * from public.jobs j
     where j.driver_id = new.driver_id
       and j.start_fahrerstandort
       and coalesce(btrim(j.pickup_address), '') = ''
  loop
    v_text := public.trisar_fahrerstandort_text(v_job);
    if v_text is not null then
      update public.jobs set pickup_address = v_text where id = v_job.id;
    end if;
  end loop;
  return new;
end;

select case when p_lat1 is null or p_lng1 is null or p_lat2 is null or p_lng2 is null then null
  else round(6371000 * 2 * asin(sqrt(
    power(sin(radians(p_lat2 - p_lat1) / 2), 2)
    + cos(radians(p_lat1)) * cos(radians(p_lat2)) * power(sin(radians(p_lng2 - p_lng1) / 2), 2)
  )))::integer end

declare
  v_fahrer uuid := auth.uid();
  v_rolle text;
  v_tracker public.obd_tracker%rowtype;
  v_vorher uuid;
  v_vorher_name text;
  v_mein_fahrzeug uuid;
  v_name text;
  v_schon boolean;
  v_trip_statuses constant text[] := array['in_progress', 'unterwegs', 'started', 'on_trip', 'ongoing', 'active'];
begin
  if v_fahrer is null then
    return jsonb_build_object('ok', false, 'grund', 'nicht_angemeldet', 'meldung', 'Bitte zuerst anmelden.');
  end if;

  select lower(coalesce(role, '')), vehicle_id into v_rolle, v_mein_fahrzeug from public.profiles where id = v_fahrer;
  select * into v_tracker from public.obd_tracker where nfc_code = lower(trim(p_code));

  if v_tracker.imei is null then
    insert into public.nfc_scan (nfc_code, driver_id, ergebnis) values (left(coalesce(p_code, ''), 64), v_fahrer, 'unbekannt');
    return jsonb_build_object('ok', false, 'grund', 'unbekannt', 'meldung', 'Diesen Tag kenne ich nicht.');
  end if;

  if v_rolle is distinct from 'fahrer' then
    insert into public.nfc_scan (nfc_code, imei, driver_id, vehicle_id, ergebnis)
      values (v_tracker.nfc_code, v_tracker.imei, v_fahrer, v_tracker.vehicle_id, 'keine_fahrer_rolle');
    return jsonb_build_object('ok', false, 'grund', 'keine_fahrer_rolle', 'meldung', 'Nur Fahrer können ein Fahrzeug übernehmen.');
  end if;

  select driver_id into v_vorher from public.imei_driver_map where imei = v_tracker.imei and is_active;

  -- Eine laufende Fahrt nicht wegnehmen, sonst reisst die Ortung mitten in der Fahrt ab.
  if v_vorher is not null and v_vorher <> v_fahrer and exists (
    select 1 from public.jobs j
    where j.driver_id = v_vorher and lower(coalesce(j.status, '')) = any (v_trip_statuses)
  ) then
    select trim(coalesce(first_name, '') || ' ' || coalesce(last_name, '')) into v_vorher_name from public.profiles where id = v_vorher;
    insert into public.nfc_scan (nfc_code, imei, driver_id, vehicle_id, vorher_driver_id, ergebnis)
      values (v_tracker.nfc_code, v_tracker.imei, v_fahrer, v_tracker.vehicle_id, v_vorher, 'laufende_fahrt');
    return jsonb_build_object('ok', false, 'grund', 'laufende_fahrt',
      'meldung', 'Dieses Fahrzeug ist gerade auf einer laufenden Fahrt von ' || v_vorher_name || '.');
  end if;

  select trim(coalesce(brand_model, '') || ' ' || coalesce(license_plate, '')) into v_name
    from public.vehicles where id = v_tracker.vehicle_id;

  v_schon := v_vorher = v_fahrer and (v_tracker.vehicle_id is null or v_mein_fahrzeug = v_tracker.vehicle_id);
  if v_schon then
    insert into public.nfc_scan (nfc_code, imei, driver_id, vehicle_id, vorher_driver_id, ergebnis)
      values (v_tracker.nfc_code, v_tracker.imei, v_fahrer, v_tracker.vehicle_id, v_vorher, 'schon_verbunden');
    return jsonb_build_object('ok', true, 'grund', 'schon_verbunden',
      'meldung', 'Du bist schon mit ' || coalesce(v_name, 'Tracker ' || v_tracker.nummer) || ' verbunden.');
  end if;

  -- Bisheriger Fahrer wird wieder ueber sein Handy geortet.
  if v_vorher is not null and v_vorher <> v_fahrer then
    update public.profiles set tracking_mode = 'app' where id = v_vorher;
    select trim(coalesce(first_name, '') || ' ' || coalesce(last_name, '')) into v_vorher_name from public.profiles where id = v_vorher;
  end if;

  -- Je Fahrer darf nur ein Tracker aktiv sein.
  update public.imei_driver_map set is_active = false where driver_id = v_fahrer and imei <> v_tracker.imei and is_active;
  insert into public.imei_driver_map (imei, driver_id, is_active)
    values (v_tracker.imei, v_fahrer, true)
    on conflict (imei) do update set driver_id = excluded.driver_id, is_active = true;
  update public.profiles set tracking_mode = 'obd' where id = v_fahrer;

  -- Ein Auto hat einen Fahrer.
  if v_tracker.vehicle_id is not null then
    update public.profiles set vehicle_id = null where vehicle_id = v_tracker.vehicle_id and id <> v_fahrer;
    update public.profiles set vehicle_id = v_tracker.vehicle_id where id = v_fahrer;
  end if;

  insert into public.nfc_scan (nfc_code, imei, driver_id, vehicle_id, vorher_driver_id, ergebnis)
    values (v_tracker.nfc_code, v_tracker.imei, v_fahrer, v_tracker.vehicle_id, v_vorher, 'uebernommen');

  return jsonb_build_object('ok', true, 'grund', 'uebernommen',
    'meldung', coalesce('Du fährst jetzt ' || v_name, 'Tracker ' || v_tracker.nummer || ' ist jetzt mit dir verbunden')
      || case when v_vorher_name is not null and v_vorher_name <> '' then '. Vorher bei ' || v_vorher_name || '.' else '.' end);
end;

declare
  v_id uuid;
  v_kern text := public.trisar_adress_kern(p_adresse);
  v_terminal text := (regexp_match(coalesce(p_adresse, ''), '(?:\mterminal\s*|\mT)([1-9])\M', 'i'))[1];
begin
  if v_terminal is not null then
    select o.id into v_id from public.orte o
     where o.name ~* ('(\mterminal\s*|\mT)' || v_terminal || '\M')
       and (p_lat is null or p_lng is null or public.trisar_luftlinie_m(p_lat, p_lng, o.lat, o.lng) <= greatest(o.radius_raus_m, 2000))
     order by case when p_lat is null then 0 else public.trisar_luftlinie_m(p_lat, p_lng, o.lat, o.lng) end
     limit 1;
    if v_id is not null then return v_id; end if;
  end if;
  if p_lat is not null and p_lng is not null then
    select o.id into v_id from public.orte o
     where public.trisar_luftlinie_m(p_lat, p_lng, o.lat, o.lng) <= o.radius_rein_m
     order by public.trisar_luftlinie_m(p_lat, p_lng, o.lat, o.lng)
     limit 1;
    if v_id is not null then return v_id; end if;
  end if;
  if v_kern is not null and length(v_kern) >= 5 then
    select o.id into v_id from public.orte o
     where public.trisar_adress_kern(o.adresse) = v_kern
       and (p_lat is null or p_lng is null or public.trisar_luftlinie_m(p_lat, p_lng, o.lat, o.lng) <= 2000)
     order by o.erstellt
     limit 1;
  end if;
  return v_id;
end;

declare
  v_schluessel text;
begin
  if tg_op = 'UPDATE'
     and new.pickup_address is not distinct from old.pickup_address
     and new.dropoff_address is not distinct from old.dropoff_address
     and new.zwischenstopps is not distinct from old.zwischenstopps
     and new.routen_punkte is not distinct from old.routen_punkte
     and new.route_fest is not distinct from old.route_fest then
    return new;
  end if;
  if coalesce(btrim(new.pickup_address), '') = '' or coalesce(btrim(new.dropoff_address), '') = '' then
    return new;
  end if;
  select value #>> '{}' into v_schluessel from public.integration_settings where key = 'edge_service_role_key';
  if coalesce(v_schluessel, '') = '' then
    return new;
  end if;
  perform net.http_post(
    url := 'http://kong:8000/functions/v1/external-sync',
    body := jsonb_build_object('reason', 'create', 'force_refresh', true, 'job_ids', jsonb_build_array(new.id)),
    headers := jsonb_build_object('Content-Type', 'application/json',
                                  'Authorization', 'Bearer ' || v_schluessel,
                                  'apikey', v_schluessel),
    timeout_milliseconds := 30000
  );
  return new;
end;

declare
  v_adressen_neu boolean;
begin
  v_adressen_neu := new.pickup_address is distinct from old.pickup_address
     or new.dropoff_address is distinct from old.dropoff_address
     or new.zwischenstopps is distinct from old.zwischenstopps;
  if v_adressen_neu and new.routen_punkte is not distinct from old.routen_punkte then
    new.routen_punkte := '[]'::jsonb;
  end if;
  if (v_adressen_neu or new.routen_punkte is distinct from old.routen_punkte)
     and new.route_fest is not distinct from old.route_fest then
    new.route_fest := null;
  end if;
  if jsonb_array_length(new.routen_punkte) = 0 then
    new.route_fest := null;
  end if;
  return new;
end;

